_PUBLIC_FINGER_GEOMETRY = None


def _sphere_geometry():
    global _PUBLIC_SPHERES
    if _PUBLIC_SPHERES is None:
        _PUBLIC_SPHERES = PublicSphereCheck()
    return _PUBLIC_SPHERES


def _finger_geometry():
    global _PUBLIC_FINGER_GEOMETRY
    if _PUBLIC_FINGER_GEOMETRY is None:
        geometry = []
        for index, neutral in enumerate(_FINGER_VERTICES):
            cloud = np.vstack([neutral+[0, q if index == 0 else -q, 0]
                               for q in (-.010, .044)])
            bounds = np.array([cloud.min(0), cloud.max(0)])
            if np.max(np.abs(bounds-_FINGER_BOUNDS[index])) > .000001:
                raise RuntimeError('Public finger mesh and URDF bounds disagree')
            hull = ConvexHull(cloud)
            edges = np.vstack([cloud[t[(i+1) % 3]]-cloud[t[i]]
                               for t in hull.simplices for i in range(3)])
            length = np.linalg.norm(edges, axis=1)
            edges = edges[length > 1e-6]/length[length > 1e-6, None]
            geometry.append((cloud[hull.vertices],
                np.unique(hull.equations[:, :3].round(7), axis=0),
                np.unique(edges.round(7), axis=0)))
        _PUBLIC_FINGER_GEOMETRY = geometry
    return _PUBLIC_FINGER_GEOMETRY


def _convex_box_gap(points, normals, edges, bounds):
    # SAT over both sets of faces and every edge cross product. Every positive
    # projected gap is a lower bound on actual Euclidean clearance.
    axes = np.vstack([np.eye(3), normals,
        np.cross(edges[:, None, :], np.eye(3)[None, :, :]).reshape(-1, 3)])
    length = np.linalg.norm(axes, axis=1)
    axes = axes[length > 1e-6]/length[length > 1e-6, None]
    projections = points @ axes.T
    middle = bounds.mean(0) @ axes.T
    radius = ((bounds[1]-bounds[0])*.5) @ np.abs(axes.T)
    gaps = np.maximum(middle-radius-projections.max(0),
                      projections.min(0)-middle-radius)
    return float(gaps.max())-.000001


def _point_box_gap(point, bounds):
    outside = np.maximum(np.maximum(bounds[0]-point, point-bounds[1]), 0.)
    if np.any(outside > 0.):
        return float(np.linalg.norm(outside))
    return -float(min(np.min(point-bounds[0]), np.min(bounds[1]-point)))


def _drawer_envelope_gap(ctx, arm, joints, drawer):
    """Robot spheres and full meshes versus conservative public cabinet voxels."""
    checker = _sphere_geometry()
    frames = checker.frames(ctx.kinematics.base_transforms[arm], joints)
    info, _ = models()
    bounds = np.asarray(info[drawer['model_key']]['bounds'])
    boxes = np.asarray(_NEIGHBOR_LAYER_BOUNDS.get(drawer['model_key'], [bounds]))
    root = np.r_[np.asarray(drawer['position'])[:2], ctx.table_z]
    yaw = float(drawer['yaw'])
    c, s = math.cos(yaw), math.sin(yaw)
    rotation = np.array([[c, -s, 0], [s, c, 0], [0, 0, 1]])
    smallest, support = float('inf'), ''
    for link, spheres in checker.config['collision_spheres'].items():
        matrix = frames[link]
        for sphere in spheres:
            world = matrix[:3, :3] @ np.asarray(sphere['center'])+matrix[:3, 3]
            local = (world-root) @ rotation
            gap = min(_point_box_gap(local, box) for box in boxes)-float(sphere['radius'])
            if gap < smallest:
                smallest, support = gap, link
    matrix = frames['link6']
    relative = rotation.T @ matrix[:3, :3]
    translation = (matrix[:3, 3]-root) @ rotation
    for index, (vertices, normals, edges) in enumerate(_finger_geometry()):
        gap = _convex_boxes_gap(vertices @ relative.T+translation,
                                normals @ relative.T, edges @ relative.T, boxes)
        if gap < smallest:
            smallest, support = gap, 'finger'+str(index)
    mesh_gap, mesh_support = _neighbor_envelope_gap(ctx, arm, joints, drawer)
    if mesh_gap < smallest:
        smallest, support = mesh_gap, mesh_support
    return smallest, support


