_ROBOT_NEIGHBOR_GEOMETRY = None

def _hull_geometry(cloud):
    hull = ConvexHull(cloud)
    edges = []
    for i, face in enumerate(hull.simplices):
        for opposite, adjacent in enumerate(hull.neighbors[i]):
            if adjacent < i:
                continue
            # Coplanar triangle diagonals are not polyhedral edges.
            if np.linalg.norm(hull.equations[i, :3]-hull.equations[adjacent, :3]) > 1e-6:
                edges.append(cloud[face[(opposite+1) % 3]]-cloud[face[(opposite+2) % 3]])
    edges = np.asarray(edges)
    length = np.linalg.norm(edges, axis=1)
    edges = edges[length > 1e-6]/length[length > 1e-6, None]
    return (cloud[hull.vertices], np.unique(hull.equations[:, :3].round(7), axis=0),
            np.unique(edges.round(7), axis=0))


def _robot_neighbor_geometry():
    global _ROBOT_NEIGHBOR_GEOMETRY
    if _ROBOT_NEIGHBOR_GEOMETRY is None:
        geometry = {link: _hull_geometry(points)
                    for link, points in _ROBOT_NEIGHBOR_VERTICES.items()}
        geometry['link6'] = _hull_geometry(_PALM_VERTICES)
        geometry.update({'finger'+str(i): shape
                         for i, shape in enumerate(_finger_geometry())})
        _ROBOT_NEIGHBOR_GEOMETRY = geometry
    return _ROBOT_NEIGHBOR_GEOMETRY


def _convex_boxes_gap(points, normals, edges, boxes):
    boxes = np.asarray(boxes, float)
    low, high = boxes[:, 0].min(0), boxes[:, 1].max(0)
    broad = float(np.maximum(low-points.max(0), points.min(0)-high).max())
    if broad >= .014:
        return broad-.000002
    near = ((boxes[:, 0] <= points.max(0)+.030) &
            (boxes[:, 1] >= points.min(0)-.030)).all(1)
    if not np.any(near):
        return .029998
    outside_gap = .029998 if np.any(~near) else float('inf')
    boxes = boxes[near]
    def project(axes, checked):
        length = np.linalg.norm(axes, axis=1)
        axes = axes[length > 1e-6]/length[length > 1e-6, None]
        projections = points @ axes.T
        middle = checked.mean(1) @ axes.T
        radius = ((checked[:, 1]-checked[:, 0])*.5) @ np.abs(axes.T)
        return np.maximum(middle-radius-projections.max(0),
                          projections.min(0)-middle-radius).max(1)
    face_gaps = project(np.vstack([np.eye(3), normals]), boxes)
    unresolved = face_gaps < .014002
    if not np.any(unresolved):
        return min(outside_gap, float(face_gaps.min())-.000002)
    edge_axes = np.cross(edges[:, None, :], np.eye(3)[None, :, :]).reshape(-1, 3)
    exact = np.maximum(face_gaps[unresolved], project(edge_axes, boxes[unresolved]))
    safe = float(face_gaps[~unresolved].min()) if np.any(~unresolved) else float('inf')
    return min(outside_gap, min(safe, float(exact.min()))-.000002)


def _neighbor_frame(ctx, item):
    info, _ = models()
    angle = float(item['yaw'])
    c, s = math.cos(angle), math.sin(angle)
    rotation = np.asarray(item.get('world_rotation',
        [[c, -s, 0], [s, c, 0], [0, 0, 1]]), float)
    boxes = _NEIGHBOR_LAYER_BOUNDS.get(item['model_key'],
                                        [info[item['model_key']]['bounds']])
    root = np.asarray(item.get('object_root',
        np.r_[np.asarray(item['position'])[:2], ctx.table_z]), float)
    boxes=np.asarray(boxes,float).copy()
    if 'object_z_range' in item:
        low,high=np.asarray(item['object_z_range'],float)
        boxes[:,0,2]-=max(0.,float(root[2]-low))
        boxes[:,1,2]+=max(0.,float(high-root[2]))
    return boxes, root, rotation


def _neighbor_envelope_gap(ctx, arm, joints, item, fingers_open=False):
    """All public arm, palm, camera and finger supports versus observed CAD."""
    frames = _sphere_geometry().frames(ctx.kinematics.base_transforms[arm], joints)
    boxes, root, rotation = _neighbor_frame(ctx, item)
    smallest, support = float('inf'), ''
    for link, (vertices, normals, edges) in _robot_neighbor_geometry().items():
        if fingers_open and link.startswith('finger'):
            vertices, normals, edges, _ = _open_hand_geometry()[1+int(link[-1])]
        matrix = frames['link6'] if link.startswith('finger') else frames[link]
        relative = rotation.T @ matrix[:3, :3]
        translation = (matrix[:3, 3]-root) @ rotation
        gap = _convex_boxes_gap(vertices @ relative.T+translation,
                                 normals @ relative.T, edges @ relative.T, boxes)
        if gap < smallest:
            smallest, support = gap, link
    return smallest, support


def _garage_open_entry_margin(ctx,arm,joints,item):
    """Keep source-body clearance while the open jaws surround its head."""
    frames=_sphere_geometry().frames(ctx.kinematics.base_transforms[arm],joints)
    boxes,root,rotation=_neighbor_frame(ctx,item)
    smallest,support=float('inf'),''
    for link,(vertices,normals,edges) in _robot_neighbor_geometry().items():
        finger=link.startswith('finger')
        if finger:
            vertices,normals,edges,_=_open_hand_geometry()[1+int(link[-1])]
        matrix=frames['link6'] if finger else frames[link]
        relative=rotation.T@matrix[:3,:3]
        translation=(matrix[:3,3]-root)@rotation
        gap=_convex_boxes_gap(vertices@relative.T+translation,normals@relative.T,
                              edges@relative.T,boxes)
        margin=gap-(.003 if finger else .008)
        if margin<smallest:
            smallest,support=margin,link
    return smallest,support


def _attached_neighbor_gap(ctx, pose, carried, item):
    boxes, root, rotation = _neighbor_frame(ctx, item)
    relative = rotation.T @ quat_matrix(pose[3:])
    translation = (np.asarray(pose[:3])-root) @ rotation
    vertices, normals, edges = carried['geometry']
    return _convex_boxes_gap(vertices @ relative.T+translation,
                             normals @ relative.T, edges @ relative.T, boxes)


def _clock_attachment(ctx, source, quat, item, offset):
    bounds, root, rotation = _clock_bounds(ctx, source, item['yaw'], offset)
    corners = _PUBLIC_ALARM_OUTER_HULL
    pose = tcp_to_link(source, quat)
    local = (corners @ rotation.T+root-pose[:3]) @ quat_matrix(quat)
    return dict(kind='alarm', geometry=_hull_geometry(local))


def _garage_attachment(ctx, source, quat, item):
    _, arrays = models()
    root, rotation = object_frame(ctx, item)
    world = np.asarray(arrays[item['model_key']+'_points'], float) @ rotation.T+root
    pose = tcp_to_link(source, quat)
    local = (world-pose[:3]) @ quat_matrix(quat)
    return dict(kind='garage', geometry=_hull_geometry(local))


def _remember_scene(ctx, observed):
    # Only RGB measurements are retained. A missing current silhouette does
    # not delete a previously observed obstacle during arm occlusion.
    stored = ctx.memory.setdefault('desk_obstacles', {})
    for kind in ('garage', 'keyboard', 'alarm', 'drawer'):
        item = observed.get(kind)
        if item is not None:
            if (kind == 'garage' and ctx.memory.get('garage_source_requires_full_pose') and
                    'world_rotation' not in item):
                continue
            stored[kind] = {k: item[k] for k in
                ('kind', 'model_key', 'position', 'yaw', 'height', 'size', 'fit_error')}
            for key in ('world_rotation', 'object_root', 'object_z_range'):
                if key in item:
                    stored[kind][key] = item[key]


def _source_recovery_initial(ctx, measured):
    hint = garage_source_hint(ctx, measured)
    if hint is None:
        return measured
    hypotheses, raw = source_pose_hypotheses(ctx,measured,hint)
    item, fitted = measure_source_garage(ctx,measured,hint,hypotheses,required=False)
    ctx.memory['garage_source_requires_full_pose'] = True
    ctx.memory['source_recovery'] = dict(trigger=hint['trigger'],hint=hint,
        initial_current_fit=fitted['best'],initial_valid=fitted['valid'],
        identity_margin=fitted['identity_margin'],needs_wrist_view=item is None)
    result = dict(measured)
    if item is not None:
        result['garage'] = item
        ctx.memory['garage_source_hypotheses'] = [item]
    else:
        result.pop('garage',None)
        ctx.memory['garage_source_hypotheses'] = hypotheses
        for index,candidate in enumerate(hypotheses):
            result['garage_observation_hypothesis_'+str(index)] = candidate
            ctx.memory.setdefault('desk_obstacles',{})[
                'garage_observation_hypothesis_'+str(index)] = candidate
    return result


def _alarm_buffer_candidates(ctx, alarm, measured):
    candidates = free_alarm_buffer(ctx,alarm,measured,return_candidates=True)
    if not ctx.memory.get('source_recovery',{}).get('needs_wrist_view'):
        return candidates
    figures = [v for v in measured.values() if isinstance(v,dict) and
               v.get('kind')=='garage' and 'world_rotation' in v]
    if not figures:
        return candidates
    direction = 1. if alarm['position'][0]>=np.median([center(v)[0] for v in figures]) else -1.
    edges = [object_world_bounds(ctx,v)[int(direction>0),0] for v in figures]
    # Prefer a visually clear buffer farther from every plausible tall body.
    # Complete grasp/carry/empty-hand exit checks still decide feasibility.
    return sorted(candidates,key=lambda p:min(direction*(p[0]-edge) for edge in edges),
                  reverse=True)


def _check_carry_path(ctx, arm, point, quat, drawer, label, samples=22,
                      start_pose=None, start_joints=None, record=True,
                      obstacles=(), carried=None, fingers_open=False,
                      joint_waypoints=None,own_source=None):
    """Audit the complete next Cartesian segment from its measured start."""
    checker = _sphere_geometry()
    start = np.asarray(ctx.state[f'{arm}_ee_pose'] if start_pose is None else start_pose, float)
    target = tcp_to_link(point, quat)
    joints = np.asarray(ctx.state[f'{arm}_arm_joint_state'] if start_joints is None else start_joints, float)
    minimum_self, minimum_drawer, max_jump = float('inf'), float('inf'), 0.
    minimum_neighbor, neighbor_support = float('inf'), ''
    minimum_source_margin=float('inf')
    if joint_waypoints is not None:
        joint_waypoints.clear()
        joint_waypoints.append(joints.copy())
    for fraction in np.linspace(1/samples, 1., samples):
        position_tol, rotation_tol = ((.0004, .002) if
            joint_waypoints is not None and fraction == 1. else (.001, .008))
        solution = ctx.kinematics.solve(arm, interpolate_pose(start, target, fraction),
            current_joints=joints, position_tol=position_tol, rotation_tol=rotation_tol,
            max_starts=1, max_nfev=140)
        if solution['status'] != 'Success':
            solution = ctx.kinematics.solve(arm, interpolate_pose(start, target, fraction),
                current_joints=joints, position_tol=position_tol, rotation_tol=rotation_tol,
                max_starts=6, max_nfev=140)
        if solution['status'] != 'Success':
            raise RuntimeError('Carry path IK failed at '+label)
        next_joints = np.asarray(solution['joint_value'], float)
        max_jump = max(max_jump, float(np.max(np.abs(next_joints-joints))))
        joints = next_joints
        self_gap = checker.check(ctx.kinematics, arm, joints)['self_gap']
        drawer_gap, _ = _drawer_envelope_gap(ctx, arm, joints, drawer)
        minimum_self = min(minimum_self, self_gap)
        minimum_drawer = min(minimum_drawer, drawer_gap)
        if max_jump > .35 and samples < 88 and self_gap >= .006 and drawer_gap >= .008:
            return _check_carry_path(ctx, arm, point, quat, drawer, label,
                samples=88, start_pose=start, start_joints=np.asarray(
                    ctx.state[f'{arm}_arm_joint_state'] if start_joints is None else start_joints),
                record=record, obstacles=obstacles, carried=carried,
                fingers_open=fingers_open, joint_waypoints=joint_waypoints,
                own_source=own_source)
        if self_gap < .006 or drawer_gap < .008 or max_jump > .35:
            raise RuntimeError(f'Carry envelope blocked: {label}, self={self_gap:.4f}, drawer={drawer_gap:.4f}, jump={max_jump:.4f}')
        pose = ctx.kinematics.forward(arm, joints)
        if own_source is not None:
            margin,support=_garage_open_entry_margin(ctx,arm,joints,own_source)
            minimum_source_margin=min(minimum_source_margin,margin)
            if margin<0:
                raise RuntimeError(f'Open hand would sweep the figurine: {label}, {support} margin={margin:.4f}')
        if carried is not None and (carried['kind']=='garage' or
                ctx.memory.get('alarm_direct_top_geometry')):
            item_gap = _attached_neighbor_gap(ctx, pose, carried, drawer)
            minimum_drawer = min(minimum_drawer, item_gap)
            if item_gap < .008:
                raise RuntimeError(f'Carried {carried["kind"]} drawer envelope blocked: {label}, gap={item_gap:.4f}')
        for item in obstacles:
            gap, support = _neighbor_envelope_gap(ctx, arm, joints, item, fingers_open)
            if carried is not None:
                object_gap = _attached_neighbor_gap(ctx, pose, carried, item)
                if object_gap < gap:
                    gap, support = object_gap, 'carried_'+carried['kind']
            if gap < minimum_neighbor:
                minimum_neighbor, neighbor_support = gap, item['kind']+':'+support
            if gap < .008:
                raise RuntimeError(f'Neighbor envelope blocked: {label}, {item["kind"]}:{support}={gap:.4f}')
        if joint_waypoints is not None:
            joint_waypoints.append(joints.copy())
    report = dict(segment=label, self_gap=minimum_self,
                  drawer_gap=minimum_drawer, joint_step=max_jump,
                  neighbor_gap=minimum_neighbor, neighbor_support=neighbor_support)
    if own_source is not None:
        report['source_margin']=minimum_source_margin
    if record:
        ctx.memory.setdefault('carry_path_checks', []).append(report)
    return target, joints, report


def _log(ctx, stage, **data):
    ctx.stage = stage
    ctx.memory.update(phase=stage, **data)


def _rotate(xy, yaw):
    c, s = math.cos(yaw), math.sin(yaw)
    return np.array([[c, -s], [s, c]]) @ np.asarray(xy, float)


def _up(point, distance):
    value = np.asarray(point, float).copy()
    value[2] += distance
    return value


def _park(ctx, duration=18):
    # At native home the open fingers project onto the mouse. Put them outside
    # the object workspaces before taking another RGB measurement.
    targets = {'left': np.array([-.48, -.36, ctx.table_z+.245]),
               'right': np.array([.48, -.36, ctx.table_z+.245])}
    if all(np.linalg.norm(ctx.tcp(arm)-targets[arm]) < .006 and
           np.linalg.norm(quat_matrix(ctx.state[arm+'_ee_pose'][3:])-
                          quat_matrix(down_quat())) < .025 for arm in targets):
        yield from ctx.hold(3)
        return
    stored = ctx.memory.get('desk_obstacles', {})
    drawer = stored.get('drawer')
    obstacles = tuple(v for k, v in stored.items() if k != 'drawer')
    if drawer is None:
        yield from ctx.move_both(targets['left'], targets['right'],
                                down_quat(), down_quat(), 1., 1., duration=duration)
        yield from ctx.hold(3)
        return
    # Never visit the horizontal native home on the way to a camera-clearing
    # pose. Its open fingers can sweep the tall figurine during the next turn.
    plans = {}
    for arm in targets:
        plans[arm] = _park_plan(ctx, arm, targets[arm], drawer, obstacles)
    count = max(len(p) for p in plans.values())
    for index in range(count):
        points = {}
        for arm in targets:
            path = plans[arm]
            point, quat = path[min(index, len(path)-1)]
            _check_carry_path(ctx, arm, point, quat, drawer,
                              'park_'+arm+'_'+str(index), obstacles=obstacles,
                              fingers_open=True, samples=88)
            points[arm] = point, quat
        yield from ctx.move_both(points['left'][0], points['right'][0],
            points['left'][1], points['right'][1], 1., 1.,
            duration=max(8, duration//count+int(index < duration % count)))
    for _ in range(8):
        if all(np.linalg.norm(ctx.tcp(a)-targets[a]) < .009 for a in targets):
            break
        yield from ctx.hold(1)
    else:
        raise RuntimeError('Observation park did not physically converge')
    yield from ctx.hold(3)


def _park_plan(ctx, arm, target, drawer, obstacles, start_pose=None, start_joints=None):
    pose = np.asarray(ctx.state[arm+'_ee_pose'] if start_pose is None else start_pose)
    joints = np.asarray(ctx.state[arm+'_arm_joint_state'] if start_joints is None else start_joints)
    current = link_to_tcp(pose)
    roof = max([ctx.table_z+.19]+[object_world_bounds(ctx,v)[1,2] if 'world_rotation' in v
                                else ctx.table_z+float(v['height']) for v in obstacles])
    candidates = [[(target, down_quat())]]
    # Move around the arm-base axis rather than crossing it at y=-.36. A
    # straight lateral segment can force a discontinuous shoulder branch.
    for y in (-.44, -.47):
        front = current.copy(); front[1] = y
        corner = np.asarray(target).copy(); corner[1] = y
        candidates.append([(front, pose[3:]), (corner, down_quat()),
                           (target, down_quat())])
    for margin in (.050, .080, .110):
        high = current.copy(); high[2] = max(current[2], roof+margin)
        candidates.append([(high, pose[3:]), (target, down_quat())])
    # A pushed keyboard can leave the inner hand near full extension. Move
    # forward at its current height, return over the calibrated arm base,
    # then gain roof clearance before the final lateral move. Four waypoints
    # share the existing 32-action keyboard exit when this fallback is needed.
    base=np.asarray(ctx.kinematics.base_transforms[arm])[:3,3]
    for front_y in (base[1]+.010,base[1]-.020):
        front=current.copy();front[1]=front_y
        side=front.copy();side[0]=base[0]-math.copysign(.060,base[0])
        high=side.copy();high[2]=max(float(target[2]),roof+.050,current[2])
        candidates.append([(front,pose[3:]),(side,down_quat()),
                           (high,down_quat()),(target,down_quat())])
    if ctx.memory.get('alarm_direct_top_geometry'):
        # The cabinet clock raises the scene-wide roof, but these front/base
        # exit candidates can pass below it. The complete clock remains in
        # every sampled collision check; it is excluded only from this height
        # heuristic, not from the obstacle set.
        local_roof=max([ctx.table_z+.19]+[object_world_bounds(ctx,v)[1,2]
            if 'world_rotation' in v else ctx.table_z+float(v['height'])
            for v in obstacles if v['kind']!='alarm'])
        for front_y in (base[1]+.010,base[1]+.10,base[1]-.020):
            front=current.copy();front[1]=front_y
            side=front.copy();side[0]=base[0]-math.copysign(.060,base[0])
            high=side.copy();high[2]=max(float(target[2]),local_roof+.050,current[2])
            candidates.append([(front,pose[3:]),(side,down_quat()),
                               (high,down_quat()),(target,down_quat())])
    rejected = []
    for path in candidates:
        next_pose, next_joints = pose, joints
        try:
            for index, (point, quat) in enumerate(path):
                next_pose, next_joints, _ = _check_carry_path(ctx, arm, point, quat,
                    drawer, 'park_preflight_'+str(index), start_pose=next_pose,
                    start_joints=next_joints, record=False, obstacles=obstacles,
                    fingers_open=True, samples=88)
            return path
        except RuntimeError as error:
            rejected.append(str(error))
    ctx.memory['park_rejected'] = dict(arm=arm, reasons=rejected)
    raise RuntimeError('No neighbor-clear observation park')


def _move(ctx, arm, point, quat, duration=16, grip=None, tolerance=.009):
    point = np.asarray(point, float)
    yield from ctx.move(arm, point, quat, grip=grip, duration=duration)
    for _ in range(8):
        error = float(np.linalg.norm(ctx.tcp(arm)-point))
        ctx.memory['motion_residual'] = dict(arm=arm, position=error)
        if error < tolerance:
            break
        yield from ctx.move(arm, point, quat, grip=grip, duration=1)
    error = float(np.linalg.norm(ctx.tcp(arm)-point))
    if error > max(.025, tolerance*3):
        raise RuntimeError(f'Organize pose did not converge: {arm} {error:.4f} m')


def _move_eased(ctx, arm, point, quat, duration, grip=0.):
    """Move a rounded grasp without abrupt tangential acceleration."""
    start = ctx.tcp(arm).copy()
    point = np.asarray(point, float)
    for fraction in np.linspace(1/duration, 1., duration):
        progress = fraction**3*(10.-15.*fraction+6.*fraction**2)
        yield from ctx.move(arm, start+(point-start)*progress, quat,
                            grip=grip, duration=1)
    yield from _move(ctx, arm, point, quat, 1, grip)


def _patch(ctx, item):
    rgb = image(ctx)
    x, y, width, height = item['bbox']
    return rgb[max(0, y):y+height, max(0, x):x+width].copy()


def _material(rgb, kind, appearance=None):
    masks = color_masks(rgb)
    hsv = cv2.cvtColor(rgb, cv2.COLOR_RGB2HSV)
    if kind == 'mouse':
        if appearance == 'red':
            h, s, v = cv2.split(hsv)
            return (((h < 6) & (v > 180)) | (h > 170)) & (s > 95) & (v > 70)
        if appearance == 'white':
            return (hsv[..., 1] < 65) & (hsv[..., 2] > 180)
        return masks['purple'] | masks['blue']
    if kind == 'garage':
        return masks['green'] | masks['yellow'] | ((hsv[..., 1] < 72) & (hsv[..., 2] > 175))
    return (hsv[..., 1] < 72) & (hsv[..., 2] > 175)


def _same_material(first, second, kind, first_region, second_region, appearance=None):
    a = _material(first, kind, appearance) & first_region
    b = _material(second, kind, appearance) & second_region
    union = int(np.count_nonzero(a | b))
    overlap = int(np.count_nonzero(a & b))
    occupied = min(float(a.sum()/max(1, first_region.sum())),
                   float(b.sum()/max(1, second_region.sum())))
    return overlap/max(1, union), min(int(a.sum()), int(b.sum())), occupied


def _alarm_source_rgb(ctx, alarm, source, offset, arm):
    """Reject a grossly changed clock before reusing its observed upright pose."""
    _, root, rotation = _clock_bounds(ctx, source, alarm['yaw'], offset)
    points = models()[1][alarm['model_key']+'_points'] @ rotation.T+root
    camera = f'cam_{arm}_wrist'
    origin, view, _, _ = ctx.perception.camera_geometry(camera, ctx.state)
    points = points[((points-origin) @ view)[:, 2] < -.015]
    mask = np.zeros(image(ctx, camera).shape[:2], np.uint8)
    if len(points) >= 4:
        pixels = project_points(ctx, points, camera)
        pixels = pixels[np.isfinite(pixels).all(1) & (np.abs(pixels) < 5000).all(1)]
        if len(pixels) >= 4:
            cv2.fillConvexPoly(mask, cv2.convexHull(pixels.astype(np.float32)).astype(np.int32), 1)
            mask = cv2.erode(mask, np.ones((3, 3), np.uint8))
    material = _material(image(ctx, camera), 'alarm') & (mask > 0)
    coverage = float(material.sum()/max(1, mask.sum()))
    ctx.memory['alarm_preclose_source'] = dict(casing_material_coverage=coverage,
        material_pixels=int(material.sum()), expected_pixels=int(mask.sum()))
    if material.sum() < 1000 or coverage < .45:
        raise RuntimeError('Alarm source CAD is inconsistent with current wrist RGB')


def _alarm_guarded_move(ctx, arm, point, quat, duration, drawer, obstacles,
                         source, alarm, offset, contact=False):
    """Emit this task's checked Cartesian branch without a joint shortcut."""
    start_pose = np.asarray(ctx.state[f'{arm}_ee_pose'], float)
    waypoints = []
    target, _, report = _check_carry_path(ctx, arm, point, quat, drawer,
        'alarm_explicit_joint_path', samples=88, obstacles=obstacles,
        fingers_open=True, joint_waypoints=waypoints)
    clock_gap = min(_clock_open_gap(ctx, ctx.kinematics.forward(arm, joints),
        source, alarm['yaw'], offset) for joints in waypoints)
    if clock_gap < .003:
        raise RuntimeError('Alarm numerical branch would sweep the casing')
    waypoints = np.asarray(waypoints)
    # Parameterize by joint arc length: a short but curved FK section needs
    # local time even when its Cartesian fraction occupies few dense samples.
    arc = np.r_[0., np.cumsum(np.max(np.abs(np.diff(waypoints, axis=0)), axis=1))]
    count = max(int(duration), int(np.ceil(np.linalg.norm(
        target[:3]-start_pose[:3])/.025)), int(np.ceil(arc[-1]/.065)))
    if count > max(32, int(duration)+16):
        raise RuntimeError('Alarm numerical path exceeds bounded action budget')
    while True:
        indices = (np.interp(np.linspace(0., arc[-1], count+1), arc,
            np.arange(len(waypoints))) if arc[-1] > 1e-9 else
            np.linspace(0., len(waypoints)-1, count+1))
        commands = np.asarray([np.interp(indices, np.arange(len(waypoints)),
            waypoints[:, joint]) for joint in range(6)]).T
        if np.max(np.abs(np.diff(commands, axis=0))) <= .075:
            break
        count += 1
        if count > max(32, int(duration)+16):
            raise RuntimeError('Alarm numerical path exceeds bounded action budget')
    # A PhysX joint action traverses between these commands. Check the entire
    # interpolation actually sent, including palm, camera and open fingers.
    checker = _sphere_geometry()
    minimum_clock, minimum_self = clock_gap, report['self_gap']
    minimum_drawer, minimum_neighbor = report['drawer_gap'], report['neighbor_gap']
    for a, b in zip(commands[:-1], commands[1:]):
        for f in np.linspace(0., 1., 7):
            joints = a+(b-a)*f
            pose = ctx.kinematics.forward(arm, joints)
            own_gap = _clock_open_gap(ctx, pose, source, alarm['yaw'], offset)
            self_gap = checker.check(ctx.kinematics, arm, joints)['self_gap']
            drawer_gap, _ = _drawer_envelope_gap(ctx, arm, joints, drawer)
            neighbor_gap = min((_neighbor_envelope_gap(ctx, arm, joints, item,
                fingers_open=True)[0] for item in obstacles), default=float('inf'))
            minimum_clock = min(minimum_clock, own_gap)
            minimum_self = min(minimum_self, self_gap)
            minimum_drawer = min(minimum_drawer, drawer_gap)
            minimum_neighbor = min(minimum_neighbor, neighbor_gap)
            if min(own_gap-.003, self_gap-.006, drawer_gap-.008,
                   neighbor_gap-.008) < 0.:
                raise RuntimeError('Alarm emitted joint interpolation violates geometry guard')
    emitted, settles = 0, 0
    ctx.gripper_targets[arm] = 1.
    for command in commands[1:]:
        while True:
            # Feedback can depart from a commanded Cartesian line. Stop before
            # continuing if the real open hand has entered the known casing.
            actual_gap = _clock_open_gap(ctx,
                np.asarray(ctx.state[f'{arm}_ee_pose']), source, alarm['yaw'], offset)
            if actual_gap < .003:
                raise RuntimeError('Measured alarm approach would sweep the casing')
            actual=np.asarray(ctx.state[f'{arm}_arm_joint_state'],float)
            for fraction in np.linspace(0.,1.,5):
                sampled=actual+(command-actual)*fraction
                self_gap=checker.check(ctx.kinematics,arm,sampled)['self_gap']
                cabinet_gap=_drawer_envelope_gap(ctx,arm,sampled,drawer)[0]
                neighbor_gap=min((_neighbor_envelope_gap(ctx,arm,sampled,item,True)[0]
                    for item in obstacles),default=float('inf'))
                own_gap=_clock_open_gap(ctx,ctx.kinematics.forward(arm,sampled),
                    source,alarm['yaw'],offset)
                if min(self_gap-.006,cabinet_gap-.008,neighbor_gap-.008,own_gap-.003)<0.:
                    raise RuntimeError(f'Actual-start alarm interpolation blocked: self={self_gap:.8f}, cabinet={cabinet_gap:.8f}, neighbor={neighbor_gap:.8f}, own={own_gap:.8f}')
            action = {}
            for name in ('left', 'right'):
                joints = (command if name == arm else np.asarray(
                    ctx.state[f'{name}_arm_joint_state'], float).copy())
                action[f'{name}_arm_joint_state'] = joints.copy()
                action[f'{name}_ee_joint_state'] = np.array([ctx.gripper_targets[name]])
                ctx.joint_targets[name] = joints.copy()
            emitted += 1
            yield action
            joint_error = np.max(np.abs(command-np.asarray(
                ctx.state[f'{arm}_arm_joint_state'], float)))
            if joint_error <= .05:
                break
            settles += 1
            if settles >= 8:
                raise RuntimeError('Alarm continuous joint path did not physically follow')
    for _ in range(8-settles):
        error = float(np.linalg.norm(ctx.tcp(arm)-np.asarray(point)))
        rotation_error=float(2*np.arccos(np.clip(abs(np.dot(
            np.asarray(ctx.state[f'{arm}_ee_pose'][3:]),np.asarray(quat))),0.,1.)))
        if error < (.0025 if contact else .005) and rotation_error<.030:
            break
        if _clock_open_gap(ctx, np.asarray(ctx.state[f'{arm}_ee_pose']),
            source, alarm['yaw'], offset) < .003:
            raise RuntimeError('Measured alarm endpoint would sweep the casing')
        emitted += 1
        yield action
    ctx.memory.setdefault('alarm_contact_controller', []).append(dict(
        actions=emitted, planned_actions=count, mode='task_continuous_joint',
        contact=contact, clock_gap=minimum_clock, self_gap=minimum_self,
        drawer_gap=minimum_drawer, neighbor_gap=minimum_neighbor,
        waypoint_joint_step=float(np.max(np.abs(np.diff(commands, axis=0))))))
    if (np.linalg.norm(ctx.tcp(arm)-np.asarray(point)) > (.003 if contact else .009) or
            float(2*np.arccos(np.clip(abs(np.dot(np.asarray(
                ctx.state[f'{arm}_ee_pose'][3:]),np.asarray(quat))),0.,1.)))>.040):
        raise RuntimeError('Alarm continuous joint endpoint did not physically converge')


def _pick(ctx, item, point, arm, quat, hover=.055, approach_points=(),
          approach_duration=22, path_drawer=None, path_obstacles=(), path_carried=None,
          probe_delta=(0., -.016)):
    before = _patch(ctx, item)
    garage_source = item if item['kind']=='garage' and 'world_rotation' in item else None
    alarm_offset = alarm_grasp_offset(item) if path_drawer is not None and item['kind'] == 'alarm' else None
    def clock_entry(target, rotation):
        if alarm_offset is not None:
            gap = _check_clock_entry(ctx, np.asarray(ctx.state[f'{arm}_ee_pose']), target, rotation, point, item['yaw'], alarm_offset)
            ctx.memory.setdefault('alarm_entry_clearances', []).append(gap)
            return gap
        return float('inf')
    def approach_move(target, rotation, duration, contact=False, tolerance=.009):
        gap = clock_entry(target, rotation)
        if alarm_offset is not None and (contact or ctx.memory.get('alarm_direct_top_in_progress') or (approach_points and gap < .080)):
            yield from _alarm_guarded_move(ctx, arm, target, rotation, duration,
                path_drawer, path_obstacles, point, item, alarm_offset, contact)
        else:
            for action in _move(ctx, arm, target, rotation, duration, 1.,tolerance=tolerance):
                if garage_source is not None:
                    margin,support=_garage_open_entry_margin(ctx,arm,
                        ctx.state[f'{arm}_arm_joint_state'],garage_source)
                    if margin<0:
                        raise RuntimeError(f'Measured open hand entered the figurine: {support}, margin={margin:.4f}')
                yield action
    _log(ctx, 'approach_'+item['kind'], active_arm=arm, grasp_point=np.asarray(point).tolist())
    for index, (waypoint, waypoint_quat, duration) in enumerate(approach_points):
        if path_drawer is not None:
            _check_carry_path(ctx, arm, waypoint, waypoint_quat, path_drawer,
                              'alarm_approach_'+str(index), obstacles=path_obstacles,
                              own_source=garage_source)
        yield from approach_move(waypoint, waypoint_quat, duration)
    if path_drawer is not None:
        _check_carry_path(ctx, arm, _up(point, hover), quat, path_drawer,
                          'alarm_hover', obstacles=path_obstacles,own_source=garage_source)
    yield from approach_move(_up(point, hover), quat, approach_duration, tolerance=.005)
    if path_drawer is not None:
        _check_carry_path(ctx, arm, point, quat, path_drawer,
                          'alarm_descend', obstacles=path_obstacles,own_source=garage_source)
    if item['kind'] == 'alarm':
        yield from approach_move(point, quat, 14, contact=True)
    else:
        yield from approach_move(point,quat,14)
    if garage_source is not None:
        margin,support=_garage_open_entry_margin(ctx,arm,
            ctx.state[f'{arm}_arm_joint_state'],garage_source)
        if margin<0:
            raise RuntimeError(f'Figurine contact reached its open support: {support}, margin={margin:.4f}')
    if item['kind'] == 'alarm':
        # Closing at the measured endpoint would otherwise freeze an accepted
        # free-space residual into the grasp. A 7 mm high casing contact can
        # slip even though the commanded contact and the path are feasible.
        position_error = float(np.linalg.norm(ctx.tcp(arm)-np.asarray(point)))
        measured_quat = np.asarray(ctx.state[f'{arm}_ee_pose'][3:], float)
        rotation_error = float(2*np.arccos(np.clip(
            abs(np.dot(measured_quat, np.asarray(quat))), 0., 1.)))
        ctx.memory['alarm_contact_residual'] = dict(position=position_error,
                                                    rotation=rotation_error)
        if position_error > .003 or rotation_error > .040:
            raise RuntimeError('Alarm contact pose did not physically converge')
        _alarm_source_rgb(ctx, item, point, alarm_offset, arm)
    _log(ctx, 'close_'+item['kind'])
    yield from ctx.grip(arm, 0., 11)
    yield from ctx.hold(3)
    _log(ctx, 'lift_'+item['kind'])
    if path_drawer is not None:
        _check_carry_path(ctx, arm, _up(point, hover), quat, path_drawer,
                          'alarm_lift', obstacles=path_obstacles, carried=path_carried)
    yield from _move(ctx, arm, _up(point, hover), quat, 14, 0.)
    yield from ctx.hold(2)
    first = image(ctx, f'cam_{arm}_wrist').copy()
    first_region = attached_object_region(ctx, item, point, quat, arm)
    # A small translation should leave the attached object's wrist appearance
    # fixed, while changing the background. No commanded closure certifies it.
    probe = _up(point, hover)
    probe[:2] += np.asarray(probe_delta)
    if path_drawer is not None:
        _check_carry_path(ctx, arm, probe, quat, path_drawer,
                          'alarm_grasp_probe', obstacles=path_obstacles, carried=path_carried)
    yield from _move(ctx, arm, probe, quat, 5, 0.)
    yield from ctx.hold(2)
    second = image(ctx, f'cam_{arm}_wrist')
    second_region = attached_object_region(ctx, item, point, quat, arm)
    appearance = item.get('appearance')
    overlap, pixels, occupancy = _same_material(first, second, item['kind'], first_region, second_region, appearance)
    opening = float(np.clip(np.asarray(ctx.state[f'{arm}_ee_joint_state']).ravel()[0], 0., 1.))
    after = _patch(ctx, item)
    difference = float(np.abs(after.astype(float)-before.astype(float)).mean()) if before.size and after.shape == before.shape else 0.
    minimum_occupancy = dict(alarm=.10, mouse=.003, garage=.015).get(item['kind'], .05)
    if item['kind'] == 'mouse' and appearance in ('red', 'white'):
        minimum_occupancy = .12
    # The gripper state is the physically limited command echo, not a measured
    # jaw opening. Attachment therefore needs positive RGB co-motion evidence.
    minimum_overlap = .82 if item['kind'] == 'alarm' else .55
    held = bool(pixels > 25 and occupancy > minimum_occupancy and overlap > minimum_overlap and difference > 12)
    ctx.memory['grasp_evidence'] = dict(kind=item['kind'], clipped_gripper_command=opening,
                                       appearance=appearance,
                                       wrist_overlap=overlap, material_pixels=pixels,
                                       material_occupancy=occupancy, source_change=difference, held=held)
    return held


def _place(ctx, arm, point, quat, hover=.055, high=None):
    if high is not None:
        raised = ctx.tcp(arm).copy()
        raised[2] = float(high)
        yield from _move(ctx, arm, raised, quat, 17, 0.)
    yield from _move(ctx, arm, _up(point, hover), quat, 22, 0.)
    yield from _move(ctx, arm, point, quat, 15, 0.)
    yield from ctx.grip(arm, 1., 9)
    yield from ctx.hold(4)
    yield from _move(ctx, arm, _up(point, hover), quat, 13, 1.)


