_PUBLIC_OPEN_GEOMETRY = None
_PUBLIC_ALARM_FACE_NORMALS = None


def _open_hand_geometry():
    global _PUBLIC_OPEN_GEOMETRY
    if _PUBLIC_OPEN_GEOMETRY is None:
        result = []
        # The hand has received full-open commands throughout the initial park.
        clouds = [_PALM_VERTICES]
        clouds += [v+[0, .044 if i == 0 else -.044, 0]
                   for i, v in enumerate(_FINGER_VERTICES)]
        frames = _sphere_geometry().frames(np.eye(4), np.zeros(6))
        inverse_tool = np.linalg.inv(frames['link6'])
        for link in ('camera_base', 'camera'):
            fixed = inverse_tool @ frames[link]
            clouds.append(_ROBOT_NEIGHBOR_VERTICES[link] @
                          fixed[:3, :3].T+fixed[:3, 3])
        for cloud in clouds:
            hull = ConvexHull(cloud)
            edges = np.vstack([cloud[t[(k+1) % 3]]-cloud[t[k]]
                for t in hull.simplices for k in range(3)])
            length = np.linalg.norm(edges, axis=1)
            edges = edges[length > 1e-6]/length[length > 1e-6, None]
            result.append((cloud[hull.vertices],
                np.unique(hull.equations[:, :3].round(7), axis=0),
                np.unique(edges.round(7), axis=0), cloud[hull.simplices]))
        _PUBLIC_OPEN_GEOMETRY = result
    return _PUBLIC_OPEN_GEOMETRY


def _clock_bounds(ctx, source, yaw, offset):
    info, _ = models()
    bounds = np.asarray(info['alarm_00000']['bounds'])
    source, offset = np.asarray(source, float), np.asarray(offset, float)
    root = np.r_[source[:2]-_rotate(offset[:2], yaw), source[2]-offset[2]]
    c, s = math.cos(yaw), math.sin(yaw)
    rotation = np.array([[c, -s, 0], [s, c, 0], [0, 0, 1]])
    return bounds, root, rotation


def _clock_open_gap(ctx, pose, source, yaw, offset):
    global _PUBLIC_ALARM_FACE_NORMALS
    bounds, root, rotation = _clock_bounds(ctx, source, yaw, offset)
    matrix = quat_matrix(pose[3:])
    relative = rotation.T @ matrix
    translation = (np.asarray(pose[:3])-root) @ rotation
    gap = float('inf')
    for vertices, normals, edges, _ in _open_hand_geometry():
        points = vertices @ relative.T+translation
        hand_normals = normals @ relative.T
        clearance = _convex_box_gap(points, hand_normals,
                                    edges @ relative.T, bounds)
        if clearance < .003:
            # The casing has rounded corners. A face projection of the
            # conservative public outer hull can certify separation where
            # its whole bounding box would occupy an empty corner.
            if _PUBLIC_ALARM_FACE_NORMALS is None:
                _PUBLIC_ALARM_FACE_NORMALS = _hull_geometry(
                    _PUBLIC_ALARM_OUTER_HULL)[1]
            axes = np.vstack([_PUBLIC_ALARM_FACE_NORMALS, hand_normals])
            axes /= np.linalg.norm(axes, axis=1)[:, None]
            hand_projection = points @ axes.T
            casing_projection = _PUBLIC_ALARM_OUTER_HULL @ axes.T
            certified = np.maximum(hand_projection.min(0)-casing_projection.max(0),
                casing_projection.min(0)-hand_projection.max(0)).max()-.000002
            clearance = max(clearance, float(certified))
        gap = min(gap, clearance)
    return gap


def _check_clock_entry(ctx, start, point, quat, source, yaw, offset, samples=22):
    target = tcp_to_link(point, quat)
    gap = min(_clock_open_gap(ctx, interpolate_pose(start, target, f), source, yaw, offset)
              for f in np.linspace(0., 1., samples+1))
    if gap < .003:
        raise RuntimeError(f'Open hand would sweep the alarm: {gap:.4f} m')
    return gap


def _alarm_side_point(ctx, source, quat, hover, yaw, offset):
    # Insert perpendicular to the jaw closing axis. Only support below the
    # clock roof can obstruct entry; higher palm/root parts pass above it.
    rotation = quat_matrix(quat)
    axis = rotation[:, 2].copy(); axis[2] = 0.
    axis /= np.linalg.norm(axis)
    if axis[0] < 0.:
        axis *= -1.
    bounds, root, clock_rotation = _clock_bounds(ctx, source, yaw, offset)
    corners = np.array([[x, y, z] for x in bounds[:, 0]
        for y in bounds[:, 1] for z in bounds[:, 2]]) @ clock_rotation.T+root
    roof = corners[:, 2].max()+.006
    clock_edge = ((corners-np.asarray(source)) @ axis).max()
    distance = .050
    for vertices, _, _, triangles in _open_hand_geometry():
        points = (vertices-[.145, 0, 0]) @ rotation.T+_up(source, hover)
        faces = (triangles-[.145, 0, 0]) @ rotation.T+_up(source, hover)
        support = [points[points[:, 2] <= roof]]
        for k in range(3):
            a, b = faces[:, k], faces[:, (k+1) % 3]
            crossing = (a[:, 2] <= roof) != (b[:, 2] <= roof)
            if np.any(crossing):
                a, b = a[crossing], b[crossing]
                support.append(a+(b-a)*((roof-a[:, 2])/(b[:, 2]-a[:, 2]))[:, None])
        support = np.concatenate(support)
        if len(support):
            near_edge = ((support-np.asarray(source)) @ axis).min()
            distance = max(distance, float(clock_edge-near_edge+.010))
    side = _up(source, hover)
    side[:2] += axis[:2]*distance
    return side, distance


def _initial_alarm_plan(ctx, source, destination, alarm_yaw, drawer, alarm_offset=None,
                        obstacles=(), prefix_cache=None):
    """Select complete cabinet-clear approaches from the current robot state."""
    rejected = []
    candidates = [('direct', 60, .070, 0., math.pi/2),
                  ('direct_routed', 60, .070, 0., math.pi/2)]
    candidates += [('side', angle, hover, 0., math.pi/2)
        for hover in (.040, .025, .015) for angle in (75, 80, 85, 90)]
    # A right-facing tool lowers flange height while a roof-clear finger tip
    # permits front entry where the side waypoint would be unreachable.
    candidates += [('roof_right', angle, hover, heading, -math.pi/2)
        for hover in (.060, .055) for heading in (math.pi-.20, math.pi, math.pi+.20)
        for angle in (45, 35, 55, 65)]
    candidates += [('roof_outboard', angle, hover, heading, -math.pi/2)
        for hover in (.060, .055) for heading in (math.pi-.20, math.pi)
        for angle in (45, 35, 55, 65)]
    candidates += [('side', angle, hover, heading, math.pi/2)
        for hover in (.015, .025, .040) for heading in (-.20, .20, -.40, .40)
        for angle in (80, 75, 85, 70)]
    # Close along the casing's long axis where a nearby tall object's head
    # obstructs the short-axis approach. These stay above the table surface.
    candidates += [('front_low', angle, hover, heading, math.pi/2)
        for hover in (.040, .055, .025) for heading in (math.pi/2, -math.pi/2)
        for angle in (30, 20, 40, 15, 35, 25)]
    rear = [('rear_low', angle, hover, math.pi/2, math.pi/2)
            for hover in (.020, .025, .030, .015) for angle in (30, 20, 40, 15, 35, 25)]
    clear = [('side_clear', angle, hover, 0., math.pi/2)
             for hover in (.055, .060) for angle in (75, 80, 70, 85)]
    # If the clock lies to the figure's left, an outboard/back entry can keep
    # the wide palm out of its head while the jaws enter along the casing.
    prefer_rear = any(v['kind'] == 'garage' and source[0] < center(v)[0]-.04
                      for v in obstacles)
    candidates = (candidates[:2]+clear+rear+candidates[2:] if prefer_rear
                  else candidates+rear+clear)
    if any(v['kind']=='garage' and 'world_rotation' in v and v['height']>.18
           for v in obstacles):
        # A complete tall-object frame makes a roof-clear front entry a useful
        # first candidate. Every approach, carry and empty-hand exit remains
        # certified against all plausible observed frames below.
        front = [('front_low', angle, hover, heading, math.pi/2)
            for hover in (.055,.040,.025) for heading in (math.pi/2,-math.pi/2)
            for angle in (30,20,40,15,35,25)]
        nearby = any(v['kind']=='garage' and
            max(0.,object_world_bounds(ctx,v)[0,0]-source[0],
                    source[0]-object_world_bounds(ctx,v)[1,0])<.100
            for v in obstacles)
        preferred = clear+front if nearby else front
        modes = {v[0] for v in preferred}
        candidates=preferred+[candidate for candidate in candidates if candidate[0] not in modes]
    candidates = [(*candidate, delta) for candidate in candidates
                  for delta in ((0., -.016), (.016, 0.), (-.016, 0.), (0., .016))]
    alarm_offset = np.zeros(3) if alarm_offset is None else np.asarray(alarm_offset)
    buffer_root = np.asarray(destination)[:2]-_rotate(alarm_offset[:2], alarm_yaw+math.pi/2)
    for mode, angle, hover, heading, object_delta, probe_delta in candidates:
        source_quat = _tilt(angle, alarm_yaw+heading)
        target_quat = _tilt(angle, alarm_yaw+heading+object_delta)
        carried = _clock_attachment(ctx, source, source_quat,
            dict(kind='alarm', yaw=alarm_yaw), alarm_offset)
        adjusted_destination = np.asarray(destination).copy()
        adjusted_destination[:2] = buffer_root+_rotate(alarm_offset[:2], alarm_yaw+object_delta)
        approach_points = []
        transport = [(_up(adjusted_destination, hover), target_quat, 22, 'alarm_buffer_hover')]
        side_distance = 0.
        if not mode.startswith('direct'):
            front = np.array([source[0], -.30, source[2]+hover])
            pivot = ctx.tcp('left').copy()
            if mode in ('roof_right', 'roof_outboard', 'front_low', 'rear_low'):
                pivot = link_to_tcp(np.r_[ctx.state['left_ee_pose'][:3], source_quat])
            approach_points = [(pivot, source_quat, 5)]
            if mode == 'rear_low':
                side, side_distance = _alarm_side_point(ctx, source, source_quat, hover, alarm_yaw, alarm_offset)
                outboard = side.copy(); outboard[0] -= .070
                approach_points += [(outboard, source_quat, 9), (side, source_quat, 7)]
            elif mode == 'side_clear':
                side, side_distance = _alarm_side_point(ctx, source, source_quat, hover, alarm_yaw, alarm_offset)
                axis = side[:2]-source[:2]; axis /= np.linalg.norm(axis)
                closing = quat_matrix(source_quat)[:2, 1]
                if closing[1] < 0.:
                    closing *= -1.
                back = _up(source, hover); back[:2] += closing*.035
                side[:2] = back[:2]+axis*(side_distance+.140)
                front = side.copy(); front[1] = -.30
                approach_points += [(front, source_quat, 8),
                                    (side, source_quat, 7), (back, source_quat, 7)]
            elif mode.startswith('side'):
                side, side_distance = _alarm_side_point(ctx, source, source_quat, hover, alarm_yaw, alarm_offset)
                front = side.copy()
                closing = quat_matrix(source_quat)[:2, 1]
                if closing[1] < 0.:
                    closing *= -1.
                if abs(closing[1]) > .25:
                    front[:2] -= closing*((front[1]+.30)/closing[1])
                else:
                    front[1] = -.30
                approach_points += [(front, source_quat, 8), (side, source_quat, 7)]
            else:
                approach_points += [(front, source_quat, 8)]
            buffer_hover = max(hover, .040)
            withdraw = np.array([source[0], adjusted_destination[1], source[2]+buffer_hover])
            transport = [(withdraw, source_quat, 16, 'alarm_withdraw'),
                         (_up(adjusted_destination, buffer_hover), source_quat, 14, 'alarm_slide_buffer'),
                         (_up(adjusted_destination, buffer_hover), target_quat, 10, 'alarm_pivot_buffer')]
            if mode == 'roof_outboard':
                clock_box, clock_root, clock_rotation = _clock_bounds(
                    ctx, source, alarm_yaw, alarm_offset)
                corners = np.array([[x, y, z] for x in clock_box[:, 0]
                    for y in clock_box[:, 1] for z in clock_box[:, 2]])
                clock_x = (corners @ clock_rotation.T+clock_root)[:, 0]
                outboard = _up(source, buffer_hover)
                for item in obstacles:
                    if item['kind'] != 'garage':
                        continue
                    bounds = object_world_bounds(ctx, item)
                    if source[0] >= center(item)[0]:
                        outboard[0] = max(outboard[0],
                            source[0]+bounds[1, 0]+.016-clock_x.min())
                    else:
                        outboard[0] = min(outboard[0],
                            source[0]+bounds[0, 0]-.016-clock_x.max())
                withdraw[0] = outboard[0]
                transport.insert(0, (outboard, source_quat, 8, 'alarm_outboard'))
            if hover < buffer_hover:
                raised_probe = _up(source, buffer_hover); raised_probe[:2] += probe_delta
                transport.insert(0, (raised_probe, source_quat, 8, 'alarm_raise_buffer'))
        else:
            buffer_hover = hover
            if mode == 'direct_routed':
                withdraw = np.array([source[0], adjusted_destination[1], source[2]+hover])
                transport = [(withdraw, source_quat, 16, 'alarm_withdraw'),
                    (_up(adjusted_destination, hover), source_quat, 14, 'alarm_slide_buffer'),
                    (_up(adjusted_destination, hover), target_quat, 10, 'alarm_pivot_buffer')]
        probe = _up(source, hover); probe[:2] += probe_delta
        segments = [(p, q, False) for p, q, _ in approach_points]
        segments += [(_up(source, hover), source_quat, False), (source, source_quat, False),
                     (_up(source, hover), source_quat, True), (probe, source_quat, True)]
        segments += [(p, q, True) for p, q, _, _ in transport]
        segments += [(adjusted_destination, target_quat, True),
                     (_up(adjusted_destination, buffer_hover), target_quat, False)]
        pose = np.asarray(ctx.state['left_ee_pose'])
        joints = np.asarray(ctx.state['left_arm_joint_state'])
        checks, clock_checks = [], []
        prefix_count = len(approach_points)+3
        key = (mode, angle, hover, heading, object_delta)
        cached = (prefix_cache or {}).get(key)
        first_segment = 0
        if cached is not None:
            if 'error' in cached:
                rejected.append(dict(mode=mode, degrees=angle, hover=hover,
                                      heading=heading, reason=cached['error']))
                continue
            pose, joints = cached['pose'].copy(), cached['joints'].copy()
            checks, clock_checks = list(cached['checks']), list(cached['clock_checks'])
            first_segment = prefix_count
        try:
            for index in range(first_segment, len(segments)):
                point, quat, holding = segments[index]
                if index <= len(approach_points)+1:
                    clock_checks.append(_check_clock_entry(ctx, pose, point, quat, source, alarm_yaw, alarm_offset))
                pose, joints, check = _check_carry_path(ctx, 'left', point, quat, drawer,
                    'initial_alarm_'+str(index), samples=22, start_pose=pose,
                    start_joints=joints, record=False, obstacles=obstacles,
                    carried=carried if holding else None)
                checks.append(check)
                if prefix_cache is not None and index == prefix_count-1:
                    prefix_cache[key] = dict(pose=pose.copy(), joints=joints.copy(),
                        checks=list(checks), clock_checks=list(clock_checks))
            # The buffer is useful only if the empty hand can subsequently
            # leave it without sweeping the released clock or tall figure.
            alarm_height = models()[0]['alarm_00000']['height']
            buffered_alarm = dict(kind='alarm', model_key='alarm_00000',
                position=np.r_[buffer_root, ctx.table_z+alarm_height*.5],
                yaw=alarm_yaw+object_delta, height=alarm_height)
            park_path = _park_plan(ctx, 'left',
                np.array([-.48, -.36, ctx.table_z+.245]), drawer,
                tuple(obstacles)+(buffered_alarm,), start_pose=pose,
                start_joints=joints)
        except RuntimeError as error:
            if prefix_cache is not None and index < prefix_count:
                prefix_cache[key] = dict(error=str(error))
            rejected.append(dict(mode=mode, degrees=angle, hover=hover, heading=heading, reason=str(error)))
            continue
        ctx.memory['alarm_initial_plan'] = dict(mode=mode, degrees=angle, hover=hover,
            tool_heading=alarm_yaw+heading, object_yaw_delta=object_delta,
            probe_delta=list(probe_delta),
            park_legs=len(park_path), park_action_budget=32+3,
            side_distance=side_distance, clock_gap=min(clock_checks),
            self_gap=min(c['self_gap'] for c in checks),
            drawer_gap=min(c['drawer_gap'] for c in checks),
            neighbor_gap=min(c['neighbor_gap'] for c in checks), rejected=rejected)
        return dict(source_quat=source_quat, target_quat=target_quat, hover=hover, buffer_hover=buffer_hover,
            destination=adjusted_destination, object_yaw_delta=object_delta,
            approach_points=approach_points, approach_duration=22 if mode.startswith('direct') else 8,
            transport=transport, obstacles=obstacles, carried=carried,
            probe_delta=probe_delta, exit_pose=pose, exit_joints=joints)
    ctx.memory['alarm_initial_plan'] = dict(rejected=rejected)
    raise RuntimeError('No cabinet-clear initial alarm path from observed geometry')


def _buffer_alarm(ctx, destination, plan, drawer):
    for point, quat, duration, stage in plan['transport']:
        _log(ctx, stage)
        _check_carry_path(ctx, 'left', point, quat, drawer, stage,
                          obstacles=plan['obstacles'], carried=plan['carried'])
        yield from _move(ctx, 'left', point, quat, duration, 0.)
    quat, hover = plan['target_quat'], plan['buffer_hover']
    _log(ctx, 'alarm_release_buffer')
    _check_carry_path(ctx, 'left', destination, quat, drawer, 'alarm_buffer_lower',
                      obstacles=plan['obstacles'], carried=plan['carried'])
    yield from _move(ctx, 'left', destination, quat, 15, 0.)
    yield from ctx.grip('left', 1., 9)
    yield from ctx.hold(4)
    _check_carry_path(ctx, 'left', _up(destination, hover), quat, drawer,
                      'alarm_buffer_retreat', obstacles=plan['obstacles'])
    yield from _move(ctx, 'left', _up(destination, hover), quat, 13, 1.)


def _alarm_destination(drawer, alarm):
    info, _ = models()
    bounds = np.asarray(info[drawer['model_key']]['bounds'])
    # Buffer contact can rotate the casing. Keep the entire public casing
    # support inside the cabinet for its currently observed orientation.
    relative_yaw = float(alarm['yaw'])-float(drawer['yaw'])
    c, s = math.cos(relative_yaw), math.sin(relative_yaw)
    outline = _PUBLIC_ALARM_OUTER_HULL[:, :2] @ np.array([[c, -s], [s, c]]).T
    local = np.array([bounds[1, 0]-outline[:, 0].max()-.014,
                      bounds[0, 1]-outline[:, 1].min()+.014])
    offset = alarm_grasp_offset(alarm)
    return np.r_[np.asarray(drawer['position'])[:2]+_rotate(local, drawer['yaw'])+
                 _rotate(offset[:2], alarm['yaw']), .765+drawer['height']+offset[2]]


def _tilt(degrees, yaw=math.pi/2):
    angle = math.radians(degrees)
    return quat_multiply([math.cos(yaw/2), 0, 0, math.sin(yaw/2)],
                         [math.cos(angle/2), 0, math.sin(angle/2), 0])


def _alarm_pose_choice(ctx, source, destination, drawer, alarm, obstacles=()):
    """Select the complete buffered-clock route from the observed robot state."""
    offset = alarm_grasp_offset(alarm)
    rejected = []
    for degrees in (30, 32, 35, 38, 40, 28, 25, 20):
        quat = _tilt(degrees)
        pose = np.asarray(ctx.state['left_ee_pose'], float)
        joints = np.asarray(ctx.state['left_arm_joint_state'], float)
        carried = _clock_attachment(ctx, source, quat, alarm, offset)
        probe = _up(source, .045)+[0., -.016, 0.]
        raised = probe.copy(); raised[2] = destination[2]+.030
        segments = (
            ('approach', _up(source, .045), False),
            ('descend', source, False),
            ('lift', _up(source, .045), True),
            ('probe', probe, True),
            ('raise', raised, True),
            ('carry', _up(destination, .030), True),
            ('place', destination, True),
            ('retreat', _up(destination, .030), False),
        )
        checks, entry_gaps = [], []
        try:
            for label, point, holding in segments:
                if label in ('approach', 'descend'):
                    entry_gaps.append(_check_clock_entry(ctx, pose, point, quat,
                                             source, alarm['yaw'], offset))
                elif label == 'retreat':
                    entry_gaps.append(_check_clock_entry(ctx, pose, point, quat,
                                             destination, alarm['yaw'], offset))
                pose, joints, report = _check_carry_path(ctx, 'left', point, quat,
                    drawer, 'final_clock_'+label, start_pose=pose,
                    start_joints=joints, record=False, obstacles=obstacles,
                    carried=carried if holding else None,
                    fingers_open=label in ('approach', 'descend', 'retreat'))
                checks.append(report)
        except RuntimeError as error:
            rejected.append(dict(degrees=degrees, reason=str(error)))
            continue
        ctx.memory['alarm_tilt_degrees'] = degrees
        ctx.memory['alarm_final_plan'] = dict(degrees=degrees, checks=checks,
            open_clock_gaps=entry_gaps, rejected=rejected)
        return quat
    ctx.memory['alarm_final_plan_rejected'] = rejected
    raise RuntimeError('No complete guarded buffered-alarm route')


def _place_alarm(ctx, point, quat, drawer, alarm, carried, obstacles=()):
    """Recheck each carrying segment and the released clock from measured poses."""
    raised = ctx.tcp('left').copy()
    raised[2] = float(point[2]+.030)
    for label, target, duration in (
            ('raise', raised, 17), ('carry', _up(point, .030), 22),
            ('place', point, 15)):
        _log(ctx, 'final_clock_'+label)
        _check_carry_path(ctx, 'left', target, quat, drawer,
                          'final_clock_'+label, obstacles=obstacles, carried=carried)
        yield from _move(ctx, 'left', target, quat, duration, 0.)
    # The complete finger travel is included in cabinet/neighbor checks before
    # opening; the clock's own casing must clear the actual open hand as well.
    offset = alarm_grasp_offset(alarm)
    gap = _clock_open_gap(ctx, np.asarray(ctx.state['left_ee_pose']),
                           point, alarm['yaw'], offset)
    if gap < .003:
        raise RuntimeError(f'Open hand would contact the placed alarm: {gap:.4f} m')
    ctx.memory.setdefault('alarm_entry_clearances', []).append(gap)
    yield from ctx.grip('left', 1., 9)
    yield from ctx.hold(4)
    _log(ctx, 'final_clock_retreat')
    gap = _check_clock_entry(ctx, np.asarray(ctx.state['left_ee_pose']),
        _up(point, .030), quat, point, alarm['yaw'], offset)
    ctx.memory.setdefault('alarm_entry_clearances', []).append(gap)
    _check_carry_path(ctx, 'left', _up(point, .030), quat, drawer,
                     'final_clock_retreat', obstacles=obstacles, fingers_open=True)
    yield from _move(ctx, 'left', _up(point, .030), quat, 13, 1.)


def _carry_pose_choice(ctx, arm, source, destination, item, source_yaw, place_yaw, hover, drawer):
    """Choose a fixed inclination with reachable, nearby wrist branches."""
    full_source = item['kind']=='garage' and 'world_rotation' in item
    if item['kind'] == 'garage':
        section, head_center = garage_grasp_geometry(item)
        head_offset = head_center[:2]
        if full_source:
            destination_root = np.asarray(destination)[:2].copy()
            source_root, source_rotation = object_frame(ctx, item)
        else:
            destination_root = np.asarray(destination)[:2]-_rotate(head_offset, item['yaw'])
        yaw_choices = (source_yaw+math.pi/2, source_yaw, source_yaw+math.pi, source_yaw-math.pi/2)
        degrees = (35, 45, 55, 65)
    else:
        section = None
        yaw_choices = (source_yaw,)
        degrees = (90, 75, 60, 45)
    choices = []
    current = np.asarray(ctx.state[f'{arm}_arm_joint_state'], float)
    destinations=[np.asarray(destination).copy()]
    if full_source:
        cabinet=object_world_bounds(ctx,drawer)
        closest=np.clip(np.asarray(destination)[:2],cabinet[0,:2],cabinet[1,:2])
        outward=np.asarray(destination)[:2]-closest
        if np.linalg.norm(outward)>.001:
            outward/=np.linalg.norm(outward)
            for amount in (.010,.020,.030):
                shifted=np.asarray(destination).copy();shifted[:2]+=outward*amount
                destinations.append(shifted)
    for yaw_index, yaw in enumerate(yaw_choices):
        if section is not None:
            # Project the public head section on the jaw's closing direction.
            relative = yaw-float(item['yaw'])
            closing = np.array([-math.sin(relative), math.cos(relative)])
            width = float(np.ptp(section[:, :2] @ closing))
            if width > .082:
                continue
        target_yaw = math.pi/2 if item['kind'] == 'garage' else place_yaw
        for destination_index,destination_at in enumerate(destinations):
            minimum_priority=destination_index*10000+yaw_index*100
            if item['kind']=='garage' and choices and min(v[0] for v in choices)<=minimum_priority:
                continue
            adjusted_destination = destination_at.copy()
            chosen_root=destination_at[:2].copy() if full_source else (
                destination_root.copy() if item['kind']=='garage' else None)
            if item['kind'] == 'garage':
                object_yaw = float(item['yaw'])+target_yaw-yaw
                adjusted_destination[:2] = chosen_root+_rotate(head_offset, object_yaw)
                if full_source:
                    adjusted_destination[2] = ctx.table_z+.001+head_center[2]
            for angle_index, angle in enumerate(degrees):
                source_quat, target_quat = _tilt(angle, yaw), _tilt(angle, target_yaw)
                carried=None
                if full_source:
                    canonical = quat_matrix(_tilt(angle,yaw-float(item['yaw'])))
                    source_quat = np.roll(Rotation.from_matrix(source_rotation@canonical).as_quat(),1)
                    carried=_garage_attachment(ctx,source,source_quat,item)
                joints = current.copy()
                cost = 0.
                for point_index,(point,quat) in enumerate(((source,source_quat),(_up(source,hover),source_quat),
                                        (_up(adjusted_destination,hover),target_quat),(adjusted_destination,target_quat))):
                    solution = ctx.kinematics.solve(arm, tcp_to_link(point, quat),
                        current_joints=joints, position_tol=.001, rotation_tol=.008,
                        max_starts=6, max_nfev=120)
                    if solution['status'] != 'Success' or solution['joint_distance'] > 3.5:
                        break
                    if _sphere_geometry().check(ctx.kinematics, arm, solution['joint_value'])['self_gap'] < .006:
                        break
                    if _drawer_envelope_gap(ctx, arm, solution['joint_value'], drawer)[0] < .008:
                        break
                    if carried is not None and point_index>=2 and _attached_neighbor_gap(
                        ctx,ctx.kinematics.forward(arm,solution['joint_value']),carried,drawer)<.008:
                        break
                    cost += solution['joint_distance']
                    joints = np.asarray(solution['joint_value'], float)
                else:
                    priority = destination_index*10000+yaw_index*100+angle_index if item['kind']=='garage' else cost
                    choices.append((priority,source_quat,target_quat,angle,yaw,adjusted_destination,chosen_root))
                    if item['kind']=='garage':
                        break
    if not choices:
        raise RuntimeError('No reachable '+item['kind']+' grasp and placement branches')
    _, source_quat, target_quat, angle, yaw, adjusted_destination,chosen_root = min(choices, key=lambda choice: choice[0])
    if item['kind']=='garage':destination_root=chosen_root
    ctx.memory['carry_orientation'] = dict(kind=item['kind'], degrees=angle, yaw=yaw)
    if item['kind'] == 'garage':
        ctx.memory['garage_transport'] = dict(source_object_yaw=float(item['yaw']),
            source_tool_yaw=yaw, target_tool_yaw=target_yaw,
            target_object_yaw=float(item['yaw'])+target_yaw-yaw,
            head_offset=head_offset.tolist(), destination_root=destination_root.tolist(),
            grasp_height=float(head_center[2]), destination_contact=adjusted_destination.tolist())
        if full_source:
            ctx.memory['garage_transport'].update(source_object_rotation=source_rotation.tolist(),
                source_object_root=source_root.tolist(),source_contact=np.asarray(source).tolist(),
                source_tool_quat=np.asarray(source_quat).tolist(),
                target_object_rotation=Rotation.from_euler('z',float(item['yaw'])+target_yaw-yaw).as_matrix().tolist())
    return source_quat, target_quat, adjusted_destination


def _garage_clear_route(ctx,current,target,quat,drawer,hover,item,alarm,carried,obstacles):
    transported=ctx.memory['garage_transport']
    carried_box=object_world_bounds(ctx,item,transported['target_object_yaw'])
    min_y=carried_box[0,1]-float(item.get('object_root',item['position'])[1])
    head_y=float(target[1]-transported['destination_root'][1])
    clock_box=object_world_bounds(ctx,alarm)
    rejected=[]
    if ctx.memory.get('alarm_direct_top_verified'):
        # A cabinet clock occupies a different corridor from the tabletop
        # buffer. Try moving inboard behind it, then advancing beside it.
        # Its measured full 3-D frame stays in both complete carry checks.
        clearance=current.copy()
        inboard=np.array([target[0],current[1],max(current[2],target[2]+hover)])
        try:
            pose,joints,first=_check_carry_path(ctx,'left',inboard,quat,drawer,
                'garage_clock_top_inboard_candidate',obstacles=obstacles,
                carried=carried,record=False)
            _,_,second=_check_carry_path(ctx,'left',_up(target,hover),quat,drawer,
                'garage_clock_top_forward_candidate',start_pose=pose,start_joints=joints,
                obstacles=obstacles,carried=carried,record=False)
            ctx.memory['clock_carry_clearance']=dict(mode='inboard_behind_clock_then_forward',
                clock_bounds=clock_box.tolist(),object_min_y=min_y,head_y=head_y,
                clearance_point=clearance.tolist(),preflight=[first,second])
            return clearance,inboard
        except RuntimeError as error:
            rejected.append(dict(mode='inboard_behind_clock_then_forward',reason=str(error)))
    for margin in ((.030,.024,.018,.016) if carried is not None else (.030,)):
        clear_y=min(float(target[1]),max(float(current[1]),
            float(clock_box[1,1]+margin-min_y+head_y)))
        clearance=current.copy();clearance[1]=clear_y
        clearance[2]=max(current[2],target[2]+hover)
        inboard=np.array([target[0],max(current[1],clear_y),
                          max(current[2],target[2]+hover)])
        try:
            pose,joints,first=_check_carry_path(ctx,'left',clearance,quat,drawer,
                'garage_clear_candidate',obstacles=obstacles,carried=carried,record=False)
            _,_,second=_check_carry_path(ctx,'left',inboard,quat,drawer,
                'garage_inboard_candidate',start_pose=pose,start_joints=joints,
                obstacles=obstacles,carried=carried,record=False)
            break
        except RuntimeError as error:
            rejected.append(dict(planned_y_gap=margin,reason=str(error)))
    else:
        raise RuntimeError('No clock-and-drawer-clear figurine route')
    ctx.memory['clock_carry_clearance']=dict(clock_bounds=clock_box.tolist(),
        object_min_y=min_y,head_y=head_y,clearance_point=clearance.tolist(),
        planned_y_gap=margin,rejected=rejected,preflight=[first,second])
    return clearance,inboard


def _place_garage(ctx, target, quat, drawer, hover, item, alarm):
    # Rotate behind the cabinet, clear the measured clock with the complete
    # carried shape, then move inboard and advance along the cabinet's side.
    current = ctx.tcp('left').copy()
    carried = None
    obstacles = ()
    if 'world_rotation' in item:
        transported = ctx.memory['garage_transport']
        carried = _garage_attachment(ctx,np.asarray(transported['source_contact']),
            np.asarray(transported['source_tool_quat']),item)
        obstacles = tuple(v for k,v in ctx.memory['desk_obstacles'].items()
                           if k not in ('garage','drawer') and v['kind']!='garage')
    _log(ctx, 'rotate_garage_for_destination')
    _check_carry_path(ctx, 'left', current, quat, drawer, 'garage_pivot',
                      obstacles=obstacles,carried=carried)
    yield from _move(ctx, 'left', current, quat, 22, 0.)
    current = ctx.tcp('left').copy()
    clearance,inboard=_garage_clear_route(ctx,current,target,quat,drawer,hover,item,alarm,
                                         carried,obstacles)
    if clearance[1]-current[1] > .002:
        _log(ctx, 'garage_clear_clock')
        _check_carry_path(ctx, 'left', clearance, quat, drawer, 'garage_clear_clock',
                          obstacles=obstacles,carried=carried)
        yield from _move(ctx, 'left', clearance, quat, 22, 0.)
    current = ctx.tcp('left').copy()
    inboard[1]=max(current[1],clearance[1])
    inboard[2]=max(current[2],target[2]+hover)
    _log(ctx, 'garage_inboard')
    _check_carry_path(ctx, 'left', inboard, quat, drawer, 'garage_inboard',
                      obstacles=obstacles,carried=carried)
    yield from _move(ctx, 'left', inboard, quat, 22, 0.)
    # Forward acceleration acts tangentially to the jaws holding the rounded
    # head. Ease into and out of this motion without changing the carry height.
    _log(ctx, 'garage_forward')
    _check_carry_path(ctx, 'left', _up(target, hover), quat, drawer, 'garage_forward',
                      obstacles=obstacles,carried=carried)
    yield from _move_eased(ctx, 'left', _up(target, hover), quat, 42, 0.)
    _log(ctx, 'garage_lower')
    _check_carry_path(ctx, 'left', target, quat, drawer, 'garage_lower',
                      obstacles=obstacles,carried=carried)
    yield from _move(ctx, 'left', target, quat, 15, 0.)
    target, quat = yield from _align_garage(ctx, item, drawer)
    # Native finger control already limits each action to 20% of travel.
    # Open directly rather than spending several more actions squeezing a
    # rounded head while the command ramps upward from fully closed.
    yield from ctx.grip('left', 1., 1)
    yield from ctx.hold(4)
    yield from _move(ctx, 'left', _up(target, hover), quat, 13, 1.)


def _align_garage(ctx, item, drawer):
    """Make the observed base level and centered before opening the jaws."""
    center_xy = np.asarray(ctx.memory['garage_transport']['destination_root'], float)
    _log(ctx, 'align_garage_base')
    history = ctx.memory.setdefault('garage_pose_feedback', [])
    yaw_hint = ctx.memory['garage_transport']['target_object_yaw']
    for attempt in range(3):
        measured = measure_carried_garage(ctx, item, center_xy, yaw_hint)
        error = measured['position'][:2]-center_xy
        history.append(dict(base_position=measured['position'].tolist(),
            xy_error=error.tolist(), tilt_degrees=float(np.degrees(measured['tilt'])),
            object_yaw=float(measured['yaw']), pixel_rms=measured['pixel_rms'],
            world_rotation=measured['rotation'].tolist(),
            min_z=measured['min_z'], views=measured['views']))
        if np.linalg.norm(error) < .010 and measured['tilt'] < .07:
            ctx.memory['garage_base_verified'] = True
            break
        # Reserve release and both arms' home, plus the buffered alarm when
        # present. The shorter second correction needs 14 nominal actions.
        remaining_reserve=(75 if ctx.memory.get('alarm_direct_top_verified') else 266)
        if ctx.memory.get('alarm_direct_top_verified'):
            ctx.memory['garage_remaining_reserve']=dict(release=1,settle=4,retract=13,
                retract_arrival=8,post_release_settle=5,home=28,home_settle=4,home_arrival=12,total=remaining_reserve)
        if attempt == 2 or (attempt == 1 and ctx.steps+14+remaining_reserve > 1000):
            if np.linalg.norm(error) > .016 or measured['tilt'] > .13:
                raise RuntimeError('Figurine base did not align in the remaining motion budget')
            ctx.memory['garage_base_verified'] = True
            break
        point = ctx.tcp('left').copy()
        original_rotation = quat_matrix(ctx.state['left_ee_pose'][3:])
        upright = Rotation.from_euler('z', measured['yaw']).as_matrix()
        correction = upright @ measured['rotation'].T
        corrected_root = point+correction@(measured['position']-point)
        goal_root = np.r_[center_xy, ctx.table_z+.001]
        goal = point+goal_root-corrected_root
        quat = np.roll(Rotation.from_matrix(correction@original_rotation).as_quat(), 1)
        history[-1].update(corrected_contact=goal.tolist(), corrected_quat=quat.tolist())
        raised = point+[0, 0, .008]
        original_quat = np.asarray(ctx.state['left_ee_pose'][3:])
        raise_frames, rotate_frames, align_frames = (5, 8, 12) if attempt == 0 else (3, 4, 6)
        suffix = str(attempt)
        carried, obstacles = None, ()
        if 'world_rotation' in item:
            held_item=dict(item,object_root=measured['position'],world_rotation=measured['rotation'])
            carried=_garage_attachment(ctx,point,original_quat,held_item)
            obstacles=tuple(v for k,v in ctx.memory['desk_obstacles'].items()
                if k not in ('garage','drawer') and v['kind']!='garage')
        _check_carry_path(ctx, 'left', raised, original_quat, drawer, 'garage_servo_raise_'+suffix,
                          obstacles=obstacles,carried=carried)
        yield from _move(ctx, 'left', raised, original_quat, raise_frames, 0.)
        _check_carry_path(ctx, 'left', raised, quat, drawer, 'garage_servo_upright_'+suffix,
                          obstacles=obstacles,carried=carried)
        yield from _move(ctx, 'left', raised, quat, rotate_frames, 0.)
        _check_carry_path(ctx, 'left', goal, quat, drawer, 'garage_servo_align_'+suffix,
                          obstacles=obstacles,carried=carried)
        yield from _move_eased(ctx, 'left', goal, quat, align_frames, 0.)
        yaw_hint = measured['yaw']
    return ctx.tcp('left').copy(), np.asarray(ctx.state['left_ee_pose'][3:])


def _mouse_destination(ctx, mat, item):
    """Use the pad's observed inboard portion with a full object margin."""
    info, _ = models()
    bounds = np.asarray(info[mat['model_key']]['bounds'])
    local = bounds.mean(0)[:2].copy()
    local[0] -= min(.035, (bounds[1, 0]-bounds[0, 0]-item['size'][0])*.35)
    local[1] -= min(.025, (bounds[1, 1]-bounds[0, 1]-item['size'][1])*.20)
    return np.r_[np.asarray(mat['position'])[:2]+_rotate(local, mat['yaw']),
                  ctx.table_z+mat['height']+item['height']*.52+.001]


def _source_camera_exit(ctx, duration=32):
    """Use the existing keyboard exit to acquire a complete source wrist view."""
    initial_step=ctx.steps
    measured=scene(ctx)
    recovery=ctx.memory['source_recovery']
    hint=garage_source_hint(ctx,measured) or recovery['hint']
    hypotheses, raw=source_pose_hypotheses(ctx,measured,hint)
    # Separate the complete scene fit from camera path search. Refresh the
    # source against the new RGB after this stationary inference boundary.
    yield from ctx.hold(1)
    hint=garage_source_hint(ctx,measured) or recovery['hint']
    hypotheses, raw=source_pose_hypotheses(ctx,measured,hint)
    drawer=measured.get('drawer') or ctx.memory['desk_obstacles']['drawer']
    obstacles=tuple(hypotheses)+tuple(measured[k] for k in ('alarm','keyboard') if measured.get(k))
    aim=np.median([v['position'] for v in hypotheses],axis=0)
    info,clouds=models();body_height=max(v['height'] for v in hypotheses)
    rejected=[]
    for extra in (.020,0.,.040):
        z=ctx.table_z+body_height+.114+extra
        camera_delta=quat_matrix(down_quat())@[-.0605,0.,.051]
        point=np.array([aim[0]+(z+camera_delta[2]-aim[2])*math.tan(math.pi/6)-camera_delta[0],aim[1],z])
        try:
            left=_park_plan(ctx,'left',point,drawer,obstacles)
            right=_park_plan(ctx,'right',np.array([.48,-.36,ctx.table_z+.245]),drawer,obstacles)
            pose,joints=ctx.state['left_ee_pose'],ctx.state['left_arm_joint_state']
            for index,(waypoint,quat) in enumerate(left):
                pose,joints,_=_check_carry_path(ctx,'left',waypoint,quat,drawer,
                    'source_view_preflight'+str(index),start_pose=pose,start_joints=joints,
                    record=False,obstacles=obstacles,fingers_open=True,samples=88)
            original=ctx.obs['state'];ctx.obs['state']=dict(original)
            ctx.obs['state']['left_ee_pose']=pose;ctx.obs['state']['left_arm_joint_state']=joints
            coverage=[]
            try:
                for candidate in hypotheses:
                    root,rotation=object_frame(ctx,candidate)
                    uv=project_points(ctx,clouds[candidate['model_key']+'_points']@rotation.T+root,'cam_left_wrist')
                    fraction=float(((uv[:,0]>15)&(uv[:,0]<625)&(uv[:,1]>15)&(uv[:,1]<465)).mean())
                    coverage.append(dict(model=candidate['model_key'],fraction=fraction))
            finally:
                ctx.obs['state']=original
            if min(v['fraction'] for v in coverage)<.995:
                raise RuntimeError('Source view would still crop plausible public geometry')
            break
        except RuntimeError as error:
            rejected.append(str(error))
    else:
        raise RuntimeError('No complete source camera exit: '+'; '.join(rejected))
    _log(ctx,'observe_garage_source',source_camera_exit=dict(point=point.tolist(),
        coverage=coverage,rejected=rejected,reuses_keyboard_exit=True,start_step=initial_step,
        planned_move_actions=duration,inference_boundary_actions=1))
    ctx.memory['garage_source_hypotheses']=hypotheses
    ctx.memory['source_recovery']['hint']=hint
    count=max(len(left),len(right))
    for index in range(count):
        targets={}
        for arm,path in (('left',left),('right',right)):
            point_at,quat=path[min(index,len(path)-1)]
            _check_carry_path(ctx,arm,point_at,quat,drawer,'source_exit_'+arm+str(index),
                samples=88,obstacles=obstacles,fingers_open=True)
            targets[arm]=(point_at,quat)
        yield from ctx.move_both(targets['left'][0],targets['right'][0],
            targets['left'][1],targets['right'][1],1.,1.,
            duration=max(8,duration//count+int(index<duration%count)))
    for _ in range(8):
        if np.linalg.norm(ctx.tcp('left')-point)<.006:
            break
        yield from ctx.hold(1)
    else:
        raise RuntimeError('Source camera exit did not physically converge')
    yield from ctx.hold(3)
    ctx.memory['source_camera_exit']['actual_yields']=ctx.steps-initial_step
    ctx.memory['source_camera_view_pending']=True


def _push_keyboard(ctx, keyboard, frame):
    _log(ctx, 'push_keyboard')
    target = np.asarray(frame, float).copy()
    quat = down_quat()
    for attempt in range(3):
        item = detect_keyboard(ctx) or keyboard
        source = center(item)
        error = target[:2]-source[:2]
        ctx.memory['keyboard_center'] = source.tolist()
        ctx.memory['keyboard_target'] = target.tolist()
        # A centered 200 x 60 mm frame is fully covered before the larger
        # keyboard's center reaches it exactly. Retain a conservative margin.
        half_width, half_depth = np.asarray(item['size'])[:2]*.5
        if (abs(error[0]) < max(.012, half_width-.100-.020) and
                abs(error[1]) < max(.012, half_depth-.030-.012) and abs(item['yaw']) < .18):
            break
        rear = source.copy(); rear[1] -= half_depth+.013; rear[2] = ctx.table_z+.020
        goal = rear.copy(); goal[:2] += error
        left, right = rear+[-.09, 0, 0], rear+[.09, 0, 0]
        yield from ctx.move_both(_up(left, .070), _up(right, .070), quat, quat, 0., 0., 18)
        yield from ctx.move_both(left, right, quat, quat, 0., 0., 14)
        for fraction in np.linspace(.125, 1., 8):
            point = rear+(goal-rear)*fraction
            yield from ctx.move_both(point+[-.09, 0, 0], point+[.09, 0, 0], quat, quat, 0., 0., 5)
        yield from ctx.move_both(_up(goal+[-.09, 0, 0], .095), _up(goal+[.09, 0, 0], .095),
                                 quat, quat, 1., 1., 15)
        postpush = detect_keyboard(ctx)
        if postpush is not None:
            _remember_scene(ctx, {'keyboard': postpush})
        needs_view=ctx.memory.get('source_recovery',{}).get('needs_wrist_view',False)
        if needs_view and postpush is not None:
            post_error=target[:2]-center(postpush)[:2]
            if (abs(post_error[0])<max(.012,half_width-.100-.020) and
                    abs(post_error[1])<max(.012,half_depth-.030-.012) and abs(postpush['yaw'])<.18):
                yield from _source_camera_exit(ctx,32)
            else:
                yield from _park(ctx,duration=32)
        else:
            yield from _park(ctx, duration=32)
        measured = detect_keyboard(ctx)
        if measured is None:
            raise RuntimeError('Keyboard silhouette missing after push')
        keyboard = measured
    ctx.memory['keyboard_final'] = center(keyboard).tolist()


def _top_clock_final_home(ctx, duration=28):
    """Audit the same native-home joint interpolation against the whole desk."""
    stored=ctx.memory['desk_obstacles'];drawer=stored['drawer']
    obstacles=tuple(item for kind,item in stored.items() if kind!='drawer')
    starts={arm:np.asarray(ctx.state[arm+'_arm_joint_state']).copy() for arm in ('left','right')}
    minimum=dict(self_gap=float('inf'),drawer_gap=float('inf'),neighbor_gap=float('inf'))
    def check(arm,joints):
        own=_sphere_geometry().check(ctx.kinematics,arm,joints)['self_gap']
        cab=_drawer_envelope_gap(ctx,arm,joints,drawer)[0]
        neighbor=min((_neighbor_envelope_gap(ctx,arm,joints,item,True)[0]
            for item in obstacles),default=float('inf'))
        minimum['self_gap']=min(minimum['self_gap'],own)
        minimum['drawer_gap']=min(minimum['drawer_gap'],cab)
        minimum['neighbor_gap']=min(minimum['neighbor_gap'],neighbor)
        if min(own-.006,cab-.008,neighbor-.008)<0.:
            raise RuntimeError(f'Complete desk home path blocked: {arm}, self={own:.8f}, cabinet={cab:.8f}, neighbor={neighbor:.8f}')
    for arm in ('left','right'):
        goal=np.asarray(ctx.initial_state[arm+'_arm_joint_state'])
        for fraction in np.linspace(0.,1.,181):check(arm,starts[arm]+(goal-starts[arm])*fraction)
    for action in ctx.home(duration=duration):
        for arm in ('left','right'):
            actual=np.asarray(ctx.state[arm+'_arm_joint_state'])
            goal=np.asarray(action[arm+'_arm_joint_state'])
            for f in np.linspace(0.,1.,7):check(arm,actual+(goal-actual)*f)
        yield action
    ctx.memory['home_complete_desk_clearance']=minimum


def _finish_home(ctx):
    """Settle the measured final home without spending unused episode padding."""
    if ctx.steps+29 > 1000:
        raise RuntimeError('Insufficient motion budget for both arms home')
    report = dict(start_step=ctx.steps, home_actions=28, settle_actions=0)
    ctx.memory['organize_action_budget'] = report
    if ctx.memory.get('alarm_direct_top_verified'):
        yield from _top_clock_final_home(ctx,28)
    else:
        yield from ctx.home(duration=28)
    for _ in range(min(4, 1000-ctx.steps)):
        yield from ctx.hold(1)
        report['settle_actions'] += 1

    def settled():
        residual = {}
        for arm in ('left', 'right'):
            measured = np.asarray(ctx.state[arm+'_ee_pose'])
            original = np.asarray(ctx.initial_state[arm+'_ee_pose'])
            position = float(np.linalg.norm(measured[:3]-original[:3]))
            rotation = float(2*np.arccos(np.clip(
                abs(np.dot(measured[3:], original[3:])), 0., 1.)))
            residual[arm] = dict(position=position, rotation=rotation)
        report['home_residual'] = residual
        report['end_step'] = ctx.steps
        # These measured-pose bounds are stricter than the public native home
        # reward. Gripper effort has already been fully open throughout home.
        return all(r['position'] < .015 and r['rotation'] < .080
                   for r in residual.values())

    for _ in range(min(12, 1000-ctx.steps)):
        if settled():
            report['home_confirmed'] = True
            return
        yield from ctx.hold(1)
        report['settle_actions'] += 1
    if not settled():
        report['home_confirmed'] = False
        raise RuntimeError('Both arms home did not physically settle in episode budget')
    report['home_confirmed'] = True


def _top_clock_plan(ctx, source, alarm, drawer, obstacles):
    """Choose the whole source, cabinet placement and open-hand exit route."""
    ctx.memory['alarm_direct_top_geometry']=True
    offset=alarm_grasp_offset(alarm)
    close=any(v['kind']=='garage' and
        np.linalg.norm(np.maximum(np.maximum(object_world_bounds(ctx,v)[0,:2]-source[:2],
        source[:2]-object_world_bounds(ctx,v)[1,:2]),0.))<.16 for v in obstacles)
    specs=([('right',45,-.15,math.pi/2,.12,.015),
            ('right',40,-.15,math.pi/2,.12,.015),
            ('right',45,-.25,math.pi/2,.16,.015)] if close else
           [('front',25,math.pi/2-.025,-.2,0.,.030),
            ('front',30,math.pi/2,-.2,0.,.030),
            ('front',20,math.pi/2-.025,-.2,0.,.030)])
    rejected=[]
    for mode,angle,heading,carry_heading,dx,top_hover in specs:
        yaw_delta=carry_heading-heading if mode=='right' else carry_heading
        q=_tilt(angle,alarm['yaw']+heading)
        qt=_tilt(angle,alarm['yaw']+heading+yaw_delta)
        placed=dict(alarm,yaw=alarm['yaw']+yaw_delta)
        target=_alarm_destination(drawer,placed)+[0,0,.018]
        carried=_clock_attachment(ctx,source,q,alarm,offset)
        if mode=='front':
            pivot=link_to_tcp(np.r_[ctx.state['left_ee_pose'][:3],q])
            high=pivot.copy();high[0]=source[0]
            approach=[(pivot,q,30),(high,q,38),
                      (np.r_[source[0],-.30,source[2]+.055],q,20)]
            probe=(0.,-.016)
            pivot_point=_up(source,.055)+[0.,-.016,0.]
            carry_steps=[('pivot',pivot_point,qt,14),
                ('raise',np.r_[pivot_point[:2],target[2]+top_hover],qt,18),
                ('carry',_up(target,top_hover),qt,22),('lower',target,qt,15)]
        else:
            initial_quat=np.asarray(ctx.state['left_ee_pose'][3:])
            view_exit=ctx.tcp('left').copy()
            roof=max(object_world_bounds(ctx,v)[1,2] for v in obstacles if v['kind']=='garage')
            view_exit[2]=min(view_exit[2],roof+.104)
            high=np.r_[source[0]+dx,-.30,view_exit[2]]
            fixed=tcp_to_link(high,initial_quat)
            pivot=link_to_tcp(np.r_[fixed[:3],q])
            side=_up(source,.055);side[0]+=dx
            front=side.copy();front[1]=min(source[1]-.065,-.24)
            approach=[(view_exit,initial_quat,8),(high,initial_quat,24),(pivot,q,24),
                      (front,q,24),(side,q,12)]
            probe=(.016,0.)
            outboard=_up(source,.055)+[.08,.02,0.]
            carry_steps=[('outboard',outboard,q,18),('pivot',outboard,qt,22),
                ('raise',np.r_[outboard[:2],target[2]+top_hover],qt,18),
                ('carry',_up(target,top_hover),qt,22),('lower',target,qt,15)]
        route=[('approach'+str(i),p,r,False,d) for i,(p,r,d) in enumerate(approach)]
        route += [('hover',_up(source,.055),q,False,24),
                  ('contact',source,q,False,14),('lift',_up(source,.055),q,True,14),
                  ('probe',_up(source,.055)+np.r_[probe,0.],q,True,5)]
        route += [(name,p,r,True,d) for name,p,r,d in carry_steps]
        retreat=_up(target,.080) if mode=='front' else _up(target,.015)+[0.,-.080,0.]
        route.append(('retreat',retreat,qt,False,16))
        pose=np.asarray(ctx.state['left_ee_pose']);joints=np.asarray(ctx.state['left_arm_joint_state']);checks=[]
        try:
            for name,p,r,holding,duration in route:
                own=None
                if name.startswith('approach') or name in ('hover','contact'):
                    own=_check_clock_entry(ctx,pose,p,r,source,alarm['yaw'],offset,samples=88)
                elif name=='retreat':
                    own=_check_clock_entry(ctx,pose,p,r,target,placed['yaw'],offset,samples=88)
                way=[]
                pose,joints,check=_check_carry_path(ctx,'left',p,r,drawer,'top_clock_'+name,
                    samples=88,start_pose=pose,start_joints=joints,record=False,
                    obstacles=obstacles,carried=carried if holding else None,
                    fingers_open=not holding,joint_waypoints=way)
                arc=float(np.max(np.abs(np.diff(np.asarray(way),axis=0)),axis=1).sum())
                count=max(duration,int(np.ceil(arc/.065)))
                if count>max(32,duration+16):
                    raise RuntimeError('Top-clock Cartesian branch exceeds segment action budget')
                check.update(point=np.asarray(p).tolist(),quat=np.asarray(r).tolist(),
                    own_clock_gap=own,nominal_joint_actions=count)
                checks.append(check)
            # Keep the whole released-clock vertical settling interval in the
            # empty exit's obstacle, until new RGB replaces the estimate.
            levels=_drawer_clock_support_levels(drawer['model_key'])
            elevated=dict(placed,object_root=np.r_[target[:2]-_rotate(offset[:2],placed['yaw']),ctx.table_z+min(levels)],
                world_rotation=Rotation.from_euler('z',placed['yaw']).as_matrix(),
                object_z_range=[ctx.table_z+min(levels),target[2]-offset[2]])
            elevated['position']=elevated['object_root']+[0,0,alarm['height']/2]
            park=_park_plan(ctx,'left',np.array([-.48,-.36,ctx.table_z+.245]),drawer,
                tuple(obstacles)+(elevated,),start_pose=pose,start_joints=joints)
        except RuntimeError as error:
            rejected.append(dict(mode=mode,degrees=angle,heading=heading,
                phase=name,reason=str(error),checks=checks))
            continue
        ctx.memory['alarm_direct_top_plan']=dict(mode=mode,degrees=angle,heading=heading,
            object_yaw_delta=yaw_delta,checks=checks,park_legs=len(park),rejected=rejected,
            all_object_geometry_checked=True,nominal_path_actions=sum(v['nominal_joint_actions'] for v in checks))
        return dict(source_quat=q,target_quat=qt,hover=.055,approach_points=approach,
            approach_duration=24,probe_delta=probe,carried=carried,transport=carry_steps,
            destination=target,placed_alarm=placed,settling_obstacle=elevated,retreat=retreat)
    ctx.memory['alarm_direct_top_rejected']=rejected
    raise RuntimeError('No complete source-to-cabinet clock path from observed geometry')


def _explicit_top_clock_move(ctx, point, quat, duration, drawer, obstacles, carried=None,
                             own_clock=None):
    """Emit only the public checked Cartesian joint branch, using measured starts."""
    way=[];start=np.asarray(ctx.state['left_ee_pose'])
    target,_,report=_check_carry_path(ctx,'left',point,quat,drawer,'top_clock_joint',
        samples=88,obstacles=obstacles,carried=carried,
        fingers_open=carried is None,joint_waypoints=way)
    way=np.asarray(way);arc=np.r_[0.,np.cumsum(np.max(np.abs(np.diff(way,axis=0)),axis=1))]
    count=max(duration,int(np.ceil(np.linalg.norm(target[:3]-start[:3])/.025)),int(np.ceil(arc[-1]/.065)))
    if count>max(32,duration+16):
        raise RuntimeError('Top-clock numerical branch exceeds bounded action budget')
    while True:
        indices=np.interp(np.linspace(0.,arc[-1],count+1),arc,np.arange(len(way))) if arc[-1]>1e-9 else np.linspace(0,len(way)-1,count+1)
        commands=np.asarray([np.interp(indices,np.arange(len(way)),way[:,j]) for j in range(6)]).T
        if np.max(np.abs(np.diff(commands,axis=0)))<=.075:break
        count+=1
        if count>max(32,duration+16):raise RuntimeError('Top-clock action retiming exceeded bounded budget')
    def clearance(joints):
        fk=ctx.kinematics.forward('left',joints)
        self_gap=_sphere_geometry().check(ctx.kinematics,'left',joints)['self_gap']
        cabinet=_drawer_envelope_gap(ctx,'left',joints,drawer)[0]
        if carried is not None:cabinet=min(cabinet,_attached_neighbor_gap(ctx,fk,carried,drawer))
        neighbor=min((_neighbor_envelope_gap(ctx,'left',joints,item,carried is None)[0]
            for item in obstacles),default=float('inf'))
        if carried is not None:
            neighbor=min(neighbor,min((_attached_neighbor_gap(ctx,fk,carried,item)
                for item in obstacles),default=float('inf')))
        own=float('inf') if own_clock is None else _clock_open_gap(ctx,fk,
            own_clock[0],own_clock[1],own_clock[2])
        if min(self_gap-.006,cabinet-.008,neighbor-.008,own-.003)<0.:
            raise RuntimeError(f'Top-clock joint interpolation blocked: self={self_gap:.8f}, cabinet={cabinet:.8f}, neighbor={neighbor:.8f}, own={own:.8f}')
    for a,b in zip(commands[:-1],commands[1:]):
        for f in np.linspace(0.,1.,7):clearance(a+(b-a)*f)
    emitted=0;settles=0
    for command in commands[1:]:
        while True:
            actual=np.asarray(ctx.state['left_arm_joint_state'],float)
            for f in np.linspace(0.,1.,5):clearance(actual+(command-actual)*f)
            action={}
            for arm in ('left','right'):
                joints=command if arm=='left' else np.asarray(ctx.state[arm+'_arm_joint_state']).copy()
                action[arm+'_arm_joint_state']=joints.copy();ctx.joint_targets[arm]=joints.copy()
                action[arm+'_ee_joint_state']=np.array([0. if carried is not None and arm=='left' else ctx.gripper_targets[arm]])
            emitted+=1;yield action
            if np.max(np.abs(command-np.asarray(ctx.state['left_arm_joint_state'])))<=.040:break
            settles+=1
            if settles>=8:raise RuntimeError('Top-clock numerical path did not physically follow')
    for _ in range(8-settles):
        current=np.asarray(ctx.state['left_ee_pose']);position=np.linalg.norm(link_to_tcp(current)-point)
        angle=2*np.arccos(np.clip(abs(np.dot(current[3:],quat)),0,1))
        if position<.003 and angle<.030:break
        clearance(np.asarray(ctx.state['left_arm_joint_state']));emitted+=1;yield action
    current=np.asarray(ctx.state['left_ee_pose'])
    position=np.linalg.norm(link_to_tcp(current)-point)
    angle=2*np.arccos(np.clip(abs(np.dot(current[3:],quat)),0,1))
    ctx.memory.setdefault('top_clock_controllers',[]).append(dict(actions=emitted,planned_actions=count,
        position_error=float(position),rotation_error=float(angle),path=report))
    if position>.005 or angle>.040:raise RuntimeError('Top-clock position and orientation did not physically converge')


def _place_top_clock(ctx, plan, drawer, obstacles):
    for name,point,quat,duration in plan['transport']:
        _log(ctx,'top_clock_'+name)
        yield from _explicit_top_clock_move(ctx,point,quat,duration,drawer,obstacles,
                                            carried=plan['carried'])
    target=plan['destination'];placed=plan['placed_alarm'];offset=alarm_grasp_offset(placed)
    gap=_clock_open_gap(ctx,np.asarray(ctx.state['left_ee_pose']),target,placed['yaw'],offset)
    if gap<.003:raise RuntimeError('Released top clock would contact the open hand')
    _log(ctx,'top_clock_release')
    yield from ctx.grip('left',1.,9);yield from ctx.hold(4)
    _log(ctx,'top_clock_retreat')
    yield from _explicit_top_clock_move(ctx,plan['retreat'],plan['target_quat'],16,
        drawer,obstacles,own_clock=(target,placed['yaw'],offset))
    root=np.asarray(plan['settling_obstacle']['object_root'])
    ctx.memory['alarm_buffer']=root.tolist()
    ctx.memory['alarm_expected_yaw']=float(placed['yaw'])
    ctx.memory['alarm_elevation']=float(drawer['height'])
    ctx.memory['desk_obstacles']['alarm']=plan['settling_obstacle']
    # The released clock is hidden by the nearby forearm in a real release
    # frame. Clear that view along a fully checked open-hand joint branch;
    # retain its entire possible settling interval as an obstacle until RGB
    # supplies the current root and orientation.
    _log(ctx,'top_clock_clear_view')
    park=_park_plan(ctx,'left',np.array([-.48,-.36,ctx.table_z+.245]),drawer,
        tuple(obstacles)+(plan['settling_obstacle'],))
    for index,(point,quat) in enumerate(park):
        yield from _explicit_top_clock_move(ctx,point,quat,
            max(8,32//len(park)+int(index<32%len(park))),drawer,
            tuple(obstacles)+(plan['settling_obstacle'],))
    yield from ctx.hold(3)
    measured=detect_alarm_near(ctx,root[:2],placed['yaw'],elevation=drawer['height'])
    if measured is None:raise RuntimeError('Placed cabinet clock missing from current RGB')
    yield from ctx.hold(2)
    second=detect_alarm_near(ctx,root[:2],placed['yaw'],elevation=drawer['height'])
    if (second is None or np.linalg.norm(second['object_root']-measured['object_root'])>.003 or
            abs((second['yaw']-measured['yaw']+math.pi)%(2*math.pi)-math.pi)>.06):
        raise RuntimeError('Placed cabinet clock did not visually settle')
    _remember_scene(ctx,{'alarm':second})
    ctx.memory['alarm_direct_top_verified']=dict(root=np.asarray(second['object_root']).tolist(),
        rotation=np.asarray(second['world_rotation']).tolist(),rms=float(second['fit_error']),
        support_margin=float(second['support_margin']),stable_rgb=True)


def _organize_program(ctx):
    """Place four measured objects, keeping drawer transport upright."""
    completed = []
    _log(ctx, 'clear_initial_view')
    yield from _park(ctx)
    _log(ctx, 'measure_organize')
    measured = _source_recovery_initial(ctx,scene(ctx))
    _remember_scene(ctx, measured)
    if ctx.memory.get('garage_source_requires_full_pose'):
        # Keep the completed RGB fit and the complete path search in separate
        # inference calls. Current RGB is remeasured at the later grasp stage.
        yield from ctx.hold(1)
    direct_top=bool(ctx.memory.get('garage_source_requires_full_pose'))
    if direct_top and ctx.memory.get('source_recovery',{}).get('needs_wrist_view'):
        _log(ctx,'initial_source_camera')
        yield from _source_camera_exit(ctx,32)
        _log(ctx,'measure_initial_complete_source')
        measured=scene(ctx)
        current,fit=measure_source_garage(ctx,measured,ctx.memory['source_recovery']['hint'],
            ctx.memory.get('garage_source_hypotheses',()),required=True)
        measured['garage']=current
        ctx.memory['initial_source_complete_fit']=dict(best=fit['best'],views=fit['views'],
            identity_margin=fit['identity_margin'],valid=fit['valid'])
        ctx.memory['garage_source_hypotheses']=[current]
        for key in tuple(ctx.memory['desk_obstacles']):
            if key.startswith('garage_observation_hypothesis_'):del ctx.memory['desk_obstacles'][key]
        _remember_scene(ctx,measured)
        ctx.memory['source_camera_view_pending']=False
        yield from ctx.hold(1)
    alarm, drawer = measured.get('alarm'), measured.get('drawer')
    if alarm is None or drawer is None:
        raise RuntimeError('Observed alarm or drawer missing')
    alarm_yaw = float(alarm['yaw'])
    offset = alarm_grasp_offset(alarm)
    source = np.r_[alarm['position'][:2]+_rotate(offset[:2], alarm_yaw), ctx.table_z+offset[2]]
    neighbors = tuple(v for k,v in measured.items() if isinstance(v,dict) and
                      v.get('kind') in ('garage','keyboard'))
    if direct_top:
        plan=_top_clock_plan(ctx,source,alarm,drawer,neighbors)
        ctx.memory['alarm_direct_top_in_progress']=True
        held=yield from _pick(ctx,alarm,source,'left',plan['source_quat'],hover=plan['hover'],
            approach_points=plan['approach_points'],approach_duration=plan['approach_duration'],
            path_drawer=drawer,path_obstacles=neighbors,path_carried=plan['carried'],
            probe_delta=plan['probe_delta'])
        if not held:raise RuntimeError('Alarm grasp not physically confirmed')
        yield from _place_top_clock(ctx,plan,drawer,neighbors)
        ctx.memory['alarm_direct_top_in_progress']=False
        completed.append('alarm')
        buffer=np.asarray(ctx.memory['alarm_buffer']);buffered_yaw=ctx.memory['alarm_expected_yaw']
    else:
        candidates = _alarm_buffer_candidates(ctx, alarm, measured)
        prefix_cache, rejected_buffers = {}, []
        for buffer in candidates:
            buffer = buffer.copy(); buffer[2] = source[2]
            contact = buffer.copy(); contact[:2] += _rotate(offset[:2], alarm_yaw+math.pi/2)
            try:
                plan = _initial_alarm_plan(ctx, source, contact, alarm_yaw, drawer, offset,
                                          obstacles=neighbors, prefix_cache=prefix_cache)
                break
            except RuntimeError as error:
                rejected_buffers.append(dict(position=buffer.tolist(), reason=str(error)))
        else:
            ctx.memory['alarm_buffer_rejected'] = rejected_buffers
            raise RuntimeError('No complete neighbor-clear alarm buffer path')
        _log(ctx, 'buffer_alarm', buffer=buffer.tolist(), alarm_buffer_rejected=rejected_buffers)
        held = yield from _pick(ctx, alarm, source, 'left', plan['source_quat'], hover=plan['hover'],
            approach_points=plan['approach_points'], approach_duration=plan['approach_duration'],
            path_drawer=drawer, path_obstacles=neighbors, path_carried=plan['carried'],
            probe_delta=plan['probe_delta'])
        if not held:
            raise RuntimeError('Alarm grasp not physically confirmed')
        _log(ctx, 'rotate_alarm_on_buffer')
        yield from _buffer_alarm(ctx, plan['destination'], plan, drawer)
        ctx.memory['alarm_buffer'] = buffer.tolist()
        buffered_yaw = alarm_yaw+plan['object_yaw_delta']
        ctx.memory['alarm_expected_yaw'] = buffered_yaw
        # Retain a conservative released-clock estimate until the next clear RGB.
        buffered_alarm = dict(ctx.memory['desk_obstacles']['alarm'])
        buffered_alarm['position'] = np.r_[buffer[:2], ctx.table_z+alarm['height']*.5]
        buffered_alarm['yaw'] = buffered_yaw
        ctx.memory['desk_obstacles']['alarm'] = buffered_alarm
    for kind in ('mouse', 'garage'):
        if kind == 'garage':
            # A mouse can initially lie in the keyboard's placement frame.
            # Remove it first so pushing the panel cannot displace its source.
            _log(ctx, 'measure_keyboard')
            measured = scene(ctx)
            _remember_scene(ctx, measured)
            if measured.get('keyboard') is None or measured.get('frame_position') is None:
                raise RuntimeError('Observed keyboard or placement frame missing')
            yield from _push_keyboard(ctx, measured['keyboard'], measured['frame_position'])
            completed.append('keyboard')
        _log(ctx, 'measure_'+kind)
        if kind=='garage' and ctx.memory.get('source_recovery',{}).get('needs_wrist_view'):
            if not ctx.memory.get('source_camera_view_pending'):
                yield from _source_camera_exit(ctx,32)
        else:
            yield from _park(ctx, duration=32)
        measured = scene(ctx)
        if kind=='garage' and ctx.memory.get('garage_source_requires_full_pose'):
            recovered,fit=measure_source_garage(ctx,measured,ctx.memory['source_recovery']['hint'],
                ctx.memory.get('garage_source_hypotheses',()),required=True)
            measured['garage']=recovered
            ctx.memory['garage_source_fit']=dict(best=fit['best'],views=fit['views'],
                identity_margin=fit['identity_margin'],valid=fit['valid'])
            stored=ctx.memory.get('desk_obstacles',{})
            for key in tuple(stored):
                if key.startswith('garage_observation_hypothesis_'):
                    del stored[key]
        _remember_scene(ctx, measured)
        item = measured.get(kind)
        destination = measured.get('mousemat') if kind == 'mouse' else measured.get('cushion_position')
        if item is None or destination is None:
            raise RuntimeError('Observed '+kind+' or its destination missing')
        source = center(item)
        offset = np.zeros(2)
        if kind == 'garage':
            _, head_center = garage_grasp_geometry(item)
            offset = head_center[:2]
            target = np.asarray(destination, float).copy()
            if 'world_rotation' in item:
                root,rotation=object_frame(ctx,item)
                source=root+rotation@head_center
            else:
                source[:2] = item['position'][:2]+_rotate(offset, item['yaw'])
                source[2] = ctx.table_z+head_center[2]
                target[:2] += _rotate(offset, item['yaw'])
                target[2] = ctx.table_z+.001+head_center[2]
            grasp_yaw = float(item['yaw'])
            place_yaw = grasp_yaw
        else:
            source[2] = ctx.table_z+item['height']*.52
            target = _mouse_destination(ctx, destination, item)
            grasp_yaw = float(item['yaw'])+math.pi/2
            place_yaw = math.pi/2  # Canonical mouse yaw 0 maps raw Y to world X.
        arm = 'left' if kind == 'garage' else 'right'
        hover = .055 if kind == 'mouse' else .050
        grasp_quat, place_quat, target = _carry_pose_choice(ctx, arm, source, target, item,
                                                   grasp_yaw, place_yaw, hover, drawer)
        guarded_source = kind=='garage' and 'world_rotation' in item
        if guarded_source:
            obstacles=tuple(v for k,v in ctx.memory['desk_obstacles'].items()
                            if k not in ('garage','drawer') and v['kind']!='garage')
            carried=_garage_attachment(ctx,source,grasp_quat,item)
            held=yield from _pick(ctx,item,source,arm,grasp_quat,hover=hover,
                path_drawer=drawer,path_obstacles=obstacles,path_carried=carried)
        else:
            held = yield from _pick(ctx, item, source, arm, grasp_quat, hover=hover)
        if not held:
            raise RuntimeError(kind+' grasp not physically confirmed')
        _log(ctx, 'place_'+kind, target=target.tolist())
        if kind == 'garage':
            alarm_observed = measured.get('alarm')
            if alarm_observed is None:
                raise RuntimeError('Buffer clock missing from RGB before figurine transport')
            yield from _place_garage(ctx, target, place_quat, drawer, hover, item, alarm_observed)
            verified = ctx.memory['garage_pose_feedback'][-1]
            placed = dict(item)
            placed['position'] = np.r_[verified['base_position'][:2],
                                       ctx.table_z+item['height']*.5]
            placed['yaw'] = verified['object_yaw']
            placed['world_rotation'] = verified['world_rotation']
            placed['object_root'] = verified['base_position']
            _remember_scene(ctx, {'garage': placed})
        else:
            yield from _place(ctx, arm, target, place_quat, hover=hover)
        if kind == 'mouse':
            yield from _park(ctx, duration=18)
        elif not direct_top:
            yield from ctx.home(arm, duration=18)
        yield from ctx.hold(5)
        completed.append(kind)

    if not direct_top:
        _log(ctx, 'measure_alarm_buffer')
        yield from _park(ctx)
        alarm = detect_alarm_near(ctx, buffer[:2], buffered_yaw)
        if alarm is None:
            raise RuntimeError('RGB alarm missing after tabletop buffer')
        offset = alarm_grasp_offset(alarm)
        source = np.r_[alarm['position'][:2]+_rotate(offset[:2], alarm['yaw']), ctx.table_z+offset[2]]
        target = _alarm_destination(drawer, alarm)
        _remember_scene(ctx, {'alarm': alarm})
        neighbors = tuple(item for kind, item in ctx.memory['desk_obstacles'].items()
                           if kind not in ('alarm', 'drawer'))
        quat = _alarm_pose_choice(ctx, source, target, drawer, alarm, neighbors)
        carried = _clock_attachment(ctx, source, quat, alarm, offset)
        held = yield from _pick(ctx, alarm, source, 'left', quat, hover=.045,
            path_drawer=drawer, path_obstacles=neighbors, path_carried=carried)
        if not held:
            raise RuntimeError('Buffered alarm grasp not physically confirmed')
        _log(ctx, 'alarm_to_drawer', target=target.tolist())
        yield from _place_alarm(ctx, target, quat, drawer, alarm, carried, neighbors)
        completed.append('alarm')
    ctx.memory['organized_objects'] = completed
    _log(ctx, 'return_home')
    yield from _finish_home(ctx)


def organize_table(ctx):
    """Keep both arms and the held figurine clear of the observed cabinet clock."""
    tracked=None;feedback_count=-1
    for action in _organize_program(ctx):
        if ctx.memory.get('alarm_direct_top_verified'):
            stored=ctx.memory['desk_obstacles'];alarm=stored['alarm']
            for arm in ('left','right'):
                gap,support=_neighbor_envelope_gap(ctx,arm,
                    np.asarray(ctx.state[arm+'_arm_joint_state']),alarm,
                    fingers_open=ctx.gripper_targets[arm]>.5)
                if gap<.008:
                    raise RuntimeError(f'Measured robot entered cabinet clock: {arm}:{support}={gap:.8f}')
            evidence=ctx.memory.get('grasp_evidence',{})
            if evidence.get('kind')=='garage' and evidence.get('held') and ctx.gripper_targets['left']<.5:
                transport=ctx.memory['garage_transport'];item=stored['garage']
                history=ctx.memory.get('garage_pose_feedback',[])
                if tracked is None or len(history)!=feedback_count:
                    if history:
                        current=history[-1]
                        item=dict(item,object_root=np.asarray(current['base_position']),
                            world_rotation=np.asarray(current['world_rotation']))
                        tracked=_garage_attachment(ctx,ctx.tcp('left'),
                            np.asarray(ctx.state['left_ee_pose'][3:]),item)
                    else:
                        tracked=_garage_attachment(ctx,np.asarray(transport['source_contact']),
                            np.asarray(transport['source_tool_quat']),item)
                    feedback_count=len(history)
                gap=_attached_neighbor_gap(ctx,np.asarray(ctx.state['left_ee_pose']),tracked,alarm)
                if gap<.008:
                    raise RuntimeError(f'Measured carried figurine entered cabinet clock: {gap:.8f}')
        yield action
